async function populateAuthorityDirectory(select: HTMLSelectElement) {
  select.innerHTML = `<option value="">Loading available authorities…</option>`;
  try { const snapshot = await getDocs(query(collection(db, "users", "authorities", "authorities"), where("isApproved", "==", true))); signupAuthorities = snapshot.docs.map(entry => ({ id: entry.id, name: String(entry.data().name || entry.data().authorityName || "Authority") })).sort((a, b) => a.name.localeCompare(b.name)); select.innerHTML = `<option value="">Select authority</option>${signupAuthorities.map(item => `<option value="${escapeHtml(item.id)}">${escapeHtml(item.name)}</option>`).join("")}<option value="__missing__">My authority is not listed</option>`; }
  catch { select.innerHTML = `<option value="">Authority directory unavailable</option><option value="__missing__">My authority is not listed</option>`; }
}

function applyTheme(theme: "light" | "dark") {
  document.documentElement.dataset.theme = theme;
  localStorage.setItem(themeKey, theme);
}
applyTheme(localStorage.getItem(themeKey) === "dark" ? "dark" : "light");

