function renderLogin(message = "") {
  document.title = "Sign in — IT Connect";
  root.innerHTML = `<main class="auth-page"><section class="auth-story"><a class="brand" href="/"><span class="brand-mark">IT</span><span>IT Connect<small>Web workspace</small></span></a><div><span class="eyebrow">Your training journey, connected</span><h1>Opportunity meets preparation.</h1><p>Find placements, manage applications and stay connected to your professional community from any device.</p></div><p class="secure-note">● Secured with Firebase Authentication</p></section><section class="auth-panel"><div class="panel-top">${themeButton()}</div><form id="login-form" class="login-card"><span class="eyebrow">Welcome back</span><h2>Sign in to IT Connect</h2><p>We’ll open the correct workspace for your account.</p>${message ? `<div class="alert">${escapeHtml(message)}</div>` : ""}<label>Email address<input id="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label>Password<input id="password" type="password" autocomplete="current-password" required placeholder="Enter your password"></label><div class="remember"><label><input id="remember" type="checkbox" checked> Keep me signed in</label><button class="text-link" id="forgot-password" type="button">Forgot password?</button></div><button class="primary" type="submit">Sign in</button><div class="divider"><span>or</span></div><button class="google" id="google" type="button">Continue with Google</button><p class="auth-switch">New to IT Connect? <a href="/app/?mode=signup#signup">Create an account</a></p><p class="legal">By continuing, you agree to our <a href="/terms.html">Terms</a> and <a href="/privacy.html">Privacy Policy</a>.</p></form></section></main>`;
  document.querySelector(".auth-switch")?.insertAdjacentHTML("afterend", `<p class="auth-switch">Have an organisation account created by IT Connect? <a href="/app/#claim-account">Claim your account</a></p>`);
  bindTheme();
  document.querySelector<HTMLFormElement>("#login-form")!.addEventListener("submit", async (event) => {
    event.preventDefault();
    const email = document.querySelector<HTMLInputElement>("#email")!.value.trim();
    const password = document.querySelector<HTMLInputElement>("#password")!.value;
    try { await signInWithEmailAndPassword(auth, email, password); } catch (error) { renderLogin(error instanceof Error ? error.message : "Sign-in failed."); }
  });
  document.querySelector<HTMLButtonElement>("#google")!.addEventListener("click", async () => {
    try { await signInWithPopup(auth, new GoogleAuthProvider()); } catch (error) { renderLogin(error instanceof Error ? error.message : "Google sign-in failed."); }
  });
  document.querySelector<HTMLButtonElement>("#forgot-password")!.addEventListener("click", async () => {
    const email = document.querySelector<HTMLInputElement>("#email")!.value.trim();
    if (!email) return renderLogin("Enter your email address first, then select Forgot password.");
    try { await sendPasswordResetEmail(auth, email); renderLogin("Password reset email sent. Check your inbox."); }
    catch (error) { renderLogin(error instanceof Error ? error.message : "Password reset failed."); }
  });
}

const claimSessionKey = "itc-pending-account-claim";

function pendingClaim(): { platformRegistrationId: string; email: string } | null {
  try { const value = JSON.parse(sessionStorage.getItem(claimSessionKey) || "null"); return value?.platformRegistrationId && value?.email ? value : null; } catch { return null; }
}

function renderClaimAccount(message = "") {
  document.title = "Claim your account — IT Connect";
  const pending = pendingClaim(); const signedIn = auth.currentUser && !auth.currentUser.isAnonymous;
  root.innerHTML = `<main class="auth-page"><section class="auth-story signup-story"><a class="brand" href="/"><span class="brand-mark">IT</span><span>IT Connect<small>Account claiming</small></span></a><div><span class="eyebrow">Existing organisation account</span><h1>Claim your IT Connect workspace.</h1><p>Use the registration ID issued by IT Connect and verify ownership of the organisation email.</p></div><p class="secure-note">● Approval and verification settings remain protected</p></section><section class="auth-panel"><div class="panel-top">${themeButton()}</div>${pending && signedIn ? `<div class="login-card claim-card"><span class="eyebrow">Verify ownership</span><h2>Check your email</h2><p>We sent a verification link to <strong>${escapeHtml(pending.email)}</strong>.</p>${message ? `<div class="alert">${escapeHtml(message)}</div>` : ""}<div class="claim-summary"><small>IT Connect registration ID</small><strong>${escapeHtml(pending.platformRegistrationId)}</strong></div><button class="primary" id="complete-claim" type="button">I have verified my email</button><button class="secondary-action" id="resend-claim-verification" type="button">Resend verification email</button><p class="auth-switch"><a href="/app/#login">Cancel and return to sign in</a></p></div>` : `<form id="claim-form" class="login-card claim-card"><span class="eyebrow">Account claiming</span><h2>Claim an organisation account</h2><p>This is for company or authority profiles previously created by IT Connect.</p>${message ? `<div class="alert">${escapeHtml(message)}</div>` : ""}<label>IT Connect registration ID<input name="platformRegistrationId" required autocomplete="off" placeholder="COMP-COMP-A1B2 or AUTH-NYSC-X7K9"></label><label>Official organisation email<input name="email" type="email" required autocomplete="email" placeholder="office@organisation.com"></label><div class="signup-passwords"><label>Create password<input name="password" type="password" minlength="8" required autocomplete="new-password" placeholder="At least 8 characters"></label><label>Confirm password<input name="confirmation" type="password" minlength="8" required autocomplete="new-password" placeholder="Repeat password"></label></div><button class="primary" type="submit">Continue and verify email</button><p class="auth-switch">Already claimed it? <a href="/app/#login">Sign in</a></p></form>`}</section></main>`;
  bindTheme();
  const form = document.querySelector<HTMLFormElement>("#claim-form");
  form?.addEventListener("submit", async event => { event.preventDefault(); const data = new FormData(form); const platformRegistrationId = String(data.get("platformRegistrationId") || "").trim().toUpperCase(); const email = String(data.get("email") || "").trim().toLowerCase(); const password = String(data.get("password") || ""); if (!/^(?:COMP|AUTH)-[A-Z0-9]{4}-[A-Z0-9]{4}(?:-[A-Z0-9]{4})?$/.test(platformRegistrationId)) return renderClaimAccount("Enter a valid IT Connect registration ID."); if (password !== String(data.get("confirmation") || "")) return renderClaimAccount("The passwords do not match."); const button = form.querySelector<HTMLButtonElement>('button[type="submit"]')!; button.disabled = true; button.textContent = "Creating secure login…"; claimInProgress = true; try { const credential = await createUserWithEmailAndPassword(auth, email, password); await sendEmailVerification(credential.user); sessionStorage.setItem(claimSessionKey, JSON.stringify({platformRegistrationId, email})); claimInProgress = false; renderClaimAccount("Verification sent. Open the email link, then return here to complete the claim."); } catch (error) { claimInProgress = false; renderClaimAccount(error instanceof Error ? error.message : "The claiming process could not be started."); } });
  document.querySelector<HTMLButtonElement>("#resend-claim-verification")?.addEventListener("click", async () => { if (!auth.currentUser) return; try { await sendEmailVerification(auth.currentUser); renderClaimAccount("A new verification email was sent."); } catch (error) { renderClaimAccount(error instanceof Error ? error.message : "Verification could not be resent."); } });
  document.querySelector<HTMLButtonElement>("#complete-claim")?.addEventListener("click", async event => { const button = event.currentTarget as HTMLButtonElement; if (!auth.currentUser || !pending) return renderClaimAccount("Your claiming session expired. Please start again."); button.disabled = true; button.textContent = "Checking verification…"; try { await auth.currentUser.reload(); if (!auth.currentUser.emailVerified) return renderClaimAccount("Your email is not verified yet. Open the verification link and try again."); const claim = httpsCallable<{platformRegistrationId: string}, {role: string; platformRegistrationId: string}>(cloudFunctions, "claimOrganisationAccount"); await claim({platformRegistrationId: pending.platformRegistrationId}); sessionStorage.removeItem(claimSessionKey); await signOut(auth); history.replaceState(null, "", "/app/#login"); renderLogin("Account claimed successfully. Sign in with your new password after administrator approval."); } catch (error) { renderClaimAccount(error instanceof Error ? error.message : "The account could not be claimed."); } });
  document.querySelector<HTMLAnchorElement>('.claim-card a[href="/app/#login"]')?.addEventListener("click", async event => { if (!auth.currentUser) return; event.preventDefault(); sessionStorage.removeItem(claimSessionKey); await signOut(auth); history.replaceState(null, "", "/app/#login"); renderLogin(); });
}

function renderSignup(message = "") {
  document.title = "Create an account — IT Connect";
  const roleFields = (role: "student" | "company" | "authority") => role === "student"
    ? `<div class="role-fields"><div class="form-section-label"><b>Student identity and school</b><small>Tell us who you are and where you study.</small></div><label>Full name<input name="name" autocomplete="name" minlength="2" required placeholder="Your full name"></label><div class="signup-grid"><label>School / institution<input name="institution" required placeholder="School, polytechnic or university"></label><label>Course of study<input name="courseOfStudy" required placeholder="e.g. Computer Science"></label><label>Department<input name="department" required placeholder="Your department"></label><label>Level<input name="level" required placeholder="e.g. ND 2 or 300 Level"></label><label>Matric number<input name="matricNumber" required placeholder="Your matric number"></label><label>Student registration number<input name="registrationNumber" required placeholder="School registration number"></label><label>State<select name="stateOfOrigin" required>${stateOptions()}</select></label><label>Gender<select name="gender" required><option value="">Select gender</option><option>Female</option><option>Male</option><option>Prefer not to say</option></select></label><label>Profile photo<input name="profileImage" type="file" accept="image/jpeg,image/png,image/webp" required><small class="field-help">JPG, PNG or WebP, maximum 5 MB.</small></label></div><label>Current address<textarea name="currentAddress" required placeholder="Where you currently live"></textarea></label></div>`
    : role === "company"
      ? `<div class="role-fields"><div class="form-section-label"><b>Company information</b><small>Your internal IT Connect registration ID is generated automatically.</small></div><label>Company name<input name="name" autocomplete="organization" minlength="2" required placeholder="Registered company name"></label><div class="platform-id-control"><label>IT Connect registration ID<input name="platformRegistrationId" id="platform-registration-id" data-auto="true" required readonly pattern="COMP-[A-Z0-9]{4}-[A-Z0-9]{4}(-[A-Z0-9]{4})?" placeholder="Start typing the company name" aria-live="polite"><small class="field-help">Generated while you type and protected from editing. Not a CAC or government registration number.</small></label></div><div class="signup-grid"><label>Industry<input name="industry" required placeholder="Select or enter your industry"></label><label>State<select name="state" required>${stateOptions()}</select></label><label>Company logo<input name="profileImage" type="file" accept="image/jpeg,image/png,image/webp" required><small class="field-help">JPG, PNG or WebP, maximum 5 MB.</small></label></div><label>Business address<textarea name="address" required placeholder="Registered business address"></textarea></label><fieldset class="authority-affiliation"><legend>Is your company under an authority or organisation?</legend><label><input type="radio" name="underAuthority" value="yes" required> Yes</label><label><input type="radio" name="underAuthority" value="no" required> No</label></fieldset><div id="authority-choice" hidden><label>Authority on IT Connect<select name="authoritySelection" id="authority-directory"></select></label><label id="missing-authority" hidden>Authority not listed<input name="requestedAuthorityName" placeholder="Enter the authority or organisation name"><small class="field-help">IT Connect can contact them about a partnership.</small></label></div></div>`
      : `<div class="role-fields"><div class="form-section-label"><b>Authority information</b><small>Official accounts require administrator verification and approval.</small></div><label>Authority / organisation name<input name="name" autocomplete="organization" minlength="2" required placeholder="Official organisation name"></label><div class="signup-grid"><label>Authority type<select name="authorityType" required><option value="">Select type</option><option>Educational institution</option><option>Government regulator</option><option>Training body</option><option>Professional body</option><option>Other organisation</option></select></label><label>Authorised contact person full name<input name="contactPerson" autocomplete="name" required placeholder="Authorised representative"></label><label>State<select name="state" required>${stateOptions()}</select></label><label>Organisation logo<input name="profileImage" type="file" accept="image/jpeg,image/png,image/webp" required><small class="field-help">JPG, PNG or WebP, maximum 5 MB.</small></label></div><div class="platform-id-control"><label>IT Connect registration ID<input name="platformRegistrationId" id="platform-registration-id" data-auto="true" required readonly pattern="AUTH-[A-Z0-9]{4}-[A-Z0-9]{4}(-[A-Z0-9]{4})?" placeholder="Start typing the authority name" aria-live="polite"><small class="field-help">Generated automatically and protected from editing.</small></label></div><label>Organisation address<textarea name="address" required placeholder="Official organisation address"></textarea></label><label>Organisation description<textarea name="description" required placeholder="Describe the authority and its responsibilities"></textarea></label></div>`;
  root.innerHTML = `<main class="auth-page"><section class="auth-story signup-story"><a class="brand" href="/"><span class="brand-mark">IT</span><span>IT Connect<small>Web workspace</small></span></a><div><span class="eyebrow">One platform, every stakeholder</span><h1>Create your IT Connect account.</h1><p>Students find placements, companies manage talent, and authorities oversee training outcomes.</p></div><p class="secure-note">● Your information is protected by Firebase</p></section><section class="auth-panel signup-panel"><div class="panel-top">${themeButton()}</div><form id="signup-form" class="login-card signup-card"><span class="eyebrow">Get started</span><h2>Create an account</h2><p>Select the account that matches how you use IT Connect.</p>${message ? `<div class="alert">${escapeHtml(message)}</div>` : ""}<fieldset class="role-picker"><legend>Account type</legend><label><input type="radio" name="role" value="student" checked><span><b>Student</b><small>Find and manage placements</small></span></label><label><input type="radio" name="role" value="company"><span><b>Company</b><small>Recruit and supervise trainees</small></span></label><label><input type="radio" name="role" value="authority"><span><b>Authority</b><small>Oversee training institutions</small></span></label></fieldset><div id="role-fields">${roleFields("student")}</div><div class="form-section-label account-label"><b>Account security</b><small>Use an email address you can access.</small></div><div class="signup-grid"><label>Phone number<input name="phoneNumber" type="tel" autocomplete="tel" required placeholder="0800 000 0000"></label><label>Email address<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label></div><div class="signup-passwords"><label>Password<input name="password" type="password" autocomplete="new-password" minlength="8" required placeholder="At least 8 characters"></label><label>Confirm password<input name="confirmation" type="password" autocomplete="new-password" minlength="8" required placeholder="Repeat password"></label></div><label class="consent"><input type="checkbox" required> I agree to the <a href="/terms.html" target="_blank">Terms</a> and <a href="/privacy.html" target="_blank">Privacy Policy</a>.</label><button class="primary" type="submit">Create account</button><p class="auth-switch">Already have an account? <a href="/app/#login">Sign in</a></p></form></section></main>`;
  bindTheme();
  let platformIdTimer = 0;
  const bindRoleFields = (role: "student" | "company" | "authority") => {
    if (role !== "student") { const idInput = document.querySelector<HTMLInputElement>("#platform-registration-id")!; const nameInput = document.querySelector<HTMLInputElement>('input[name="name"]')!; const categoryInput = document.querySelector<HTMLInputElement | HTMLSelectElement>(role === "authority" ? 'select[name="authorityType"]' : 'input[name="industry"]')!; const emailInput = document.querySelector<HTMLInputElement>('input[name="email"]')!; const regenerate = () => { idInput.value = nameInput.value.trim() ? generatePlatformRegistrationId(role, nameInput.value, categoryInput.value, emailInput.value) : ""; }; const schedule = () => { window.clearTimeout(platformIdTimer); platformIdTimer = window.setTimeout(regenerate, 300); }; [nameInput, categoryInput, emailInput].forEach(input => input.addEventListener("input", schedule)); schedule(); }
    if (role !== "company") return;
    const choice = document.querySelector<HTMLDivElement>("#authority-choice")!; const directory = document.querySelector<HTMLSelectElement>("#authority-directory")!; const missing = document.querySelector<HTMLElement>("#missing-authority")!; const missingInput = missing.querySelector<HTMLInputElement>("input")!; document.querySelectorAll<HTMLInputElement>('input[name="underAuthority"]').forEach(input => input.addEventListener("change", () => { const enabled = input.value === "yes" && input.checked; choice.hidden = !enabled; directory.required = enabled; if (!enabled) { directory.value = ""; missing.hidden = true; missingInput.required = false; missingInput.value = ""; } })); directory.addEventListener("change", () => { const manual = directory.value === "__missing__"; missing.hidden = !manual; missingInput.required = manual; if (!manual) missingInput.value = ""; }); void populateAuthorityDirectory(directory);
  };
  bindRoleFields("student");
  document.querySelectorAll<HTMLInputElement>('input[name="role"]').forEach(input => input.addEventListener("change", () => { const role = input.value as "student" | "company" | "authority"; document.querySelector<HTMLDivElement>("#role-fields")!.innerHTML = roleFields(role); bindRoleFields(role); }));
  document.querySelector<HTMLFormElement>("#signup-form")!.addEventListener("submit", async event => {
    event.preventDefault(); const form = event.currentTarget as HTMLFormElement; const button = form.querySelector<HTMLButtonElement>('button[type="submit"]')!;
    const formData = new FormData(form); const role = formData.get("role") as "student" | "company" | "authority";
    const name = String(formData.get("name") || "").trim(); const email = String(formData.get("email") || "").trim().toLowerCase(); const password = String(formData.get("password") || ""); const confirmation = String(formData.get("confirmation") || "");
    if (password !== confirmation) return renderSignup("The passwords do not match.");
    const phoneNumber = String(formData.get("phoneNumber") || "").replace(/[\s()-]/g, "");
    if (!/^(?:(?:\+?234)|0)[789][01]\d{8}$/.test(phoneNumber) && !/^\+[1-9]\d{7,14}$/.test(phoneNumber)) return renderSignup("Enter a valid Nigerian or international phone number.");
    const image = formData.get("profileImage");
    if (!(image instanceof File) || !image.size) return renderSignup(`Select a ${role === "student" ? "profile photo" : "logo"}.`);
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(image.type)) return renderSignup("The image must be a JPG, PNG, or WebP file.");
    if (image.size > 5 * 1024 * 1024) return renderSignup("The image must be 5 MB or smaller.");
    if (role === "company" && formData.get("underAuthority") === "yes" && !String(formData.get("authoritySelection") || "")) return renderSignup("Select your authority, or choose that it is not listed.");
    const platformIdInput = form.querySelector<HTMLInputElement>("#platform-registration-id"); if (role !== "student" && (!platformIdInput || !isPlatformRegistrationId(platformIdInput.value, role))) return renderSignup("Enter a valid IT Connect registration ID or select Regenerate.");
    const registrationProfile = Object.fromEntries([...formData.entries()].filter(([key, value]) => typeof value === "string" && !["role", "email", "password", "confirmation"].includes(key)).map(([key, value]) => [key, String(value).trim()])) as Record<string, string> & { name: string; phoneNumber: string; imageUrl: string };
    if (platformIdInput) registrationProfile.platformRegistrationIdAuto = "true";
    if (role === "company" && registrationProfile.authoritySelection && registrationProfile.authoritySelection !== "__missing__") registrationProfile.selectedAuthorityName = signupAuthorities.find(item => item.id === registrationProfile.authoritySelection)?.name || "";
    registrationProfile.phoneNumber = phoneNumber; let uploadedImage: ReturnType<typeof ref> | null = null; let createdUid = "";
    registrationInProgress = true; button.disabled = true; button.textContent = "Creating account…";
    try {
      const credential = await createUserWithEmailAndPassword(auth, email, password); createdUid = credential.user.uid; await updateProfile(credential.user, { displayName: name });
      button.textContent = role === "student" ? "Uploading photo…" : "Uploading logo…"; const extension = image.type === "image/png" ? "png" : image.type === "image/webp" ? "webp" : "jpg"; uploadedImage = ref(storage, `registration/${role}/${createdUid}/profile.${extension}`); await uploadBytes(uploadedImage, image, { contentType: image.type }); registrationProfile.imageUrl = await getDownloadURL(uploadedImage);
      button.textContent = "Saving profile…"; await createRoleProfile(createdUid, email, role, registrationProfile); await sendEmailVerification(credential.user); registrationInProgress = false;
      const resolvedProfile = await resolveProfile(credential.user);
      if (role === "student") renderWorkspace(resolvedProfile);
      else { await signOut(auth); history.replaceState(null, "", "/app/#login"); renderLogin(`${role === "company" ? "Company" : "Authority"} registration submitted. Your IT Connect registration ID is ${registrationProfile.platformRegistrationId}. Save it securely. Verify your email now; workspace access begins after administrator approval.`); }
    } catch (error) { if (uploadedImage) try { await deleteObject(uploadedImage); } catch { /* Best-effort removal of an incomplete upload. */ } if (createdUid && auth.currentUser?.uid === createdUid) try { await deleteUser(auth.currentUser); } catch { /* The login screen provides a recoverable retry path. */ } registrationInProgress = false; button.disabled = false; renderSignup(`${error instanceof Error ? error.message : "Account creation failed."} No incomplete profile was kept; please try again.`); }
  });
}

function hydrateGlobalAvatar(profile: AccountProfile, selector = ".main>header .avatar") {
  document.querySelectorAll<HTMLElement>(".brand-mark").forEach(mark => { mark.textContent = ""; mark.classList.add("it-connect-rocket"); mark.setAttribute("role", "img"); mark.setAttribute("aria-label", "IT Connect rocket logo"); });
  const avatar = document.querySelector<HTMLElement>(selector); if (!avatar) return;
  const href = profile.role === "company" ? "#company-profile" : profile.role === "authority" ? "#authority-profile" : "#profile";
  const link = document.createElement("a"); link.className = avatar.className; link.href = href; link.setAttribute("aria-label", `Open ${profile.name}'s profile`); link.title = "Open profile";
  link.innerHTML = profile.imageUrl ? `<img src="${escapeHtml(profile.imageUrl)}" alt="${escapeHtml(profile.name)}">` : escapeHtml(profile.name.slice(0, 1).toUpperCase() || "I");
  avatar.replaceWith(link);
}

function bindMobileNavigation() {
  const workspace = document.querySelector<HTMLElement>(".workspace");
  const sidebar = document.querySelector<HTMLElement>(".sidebar");
  const toggle = document.querySelector<HTMLButtonElement>(".mobile-menu");
  if (!workspace || !sidebar || !toggle) return;

  toggle.type = "button";
  toggle.setAttribute("aria-expanded", "false");
  toggle.setAttribute("aria-controls", "workspace-navigation");
  sidebar.id = "workspace-navigation";

  const backdrop = document.createElement("button");
  backdrop.type = "button";
  backdrop.className = "sidebar-backdrop";
  backdrop.setAttribute("aria-label", "Close navigation");
  workspace.append(backdrop);

  const close = () => {
    workspace.classList.remove("navigation-open");
    toggle.setAttribute("aria-expanded", "false");
    document.body.classList.remove("mobile-navigation-open");
  };
  const open = () => {
    workspace.classList.add("navigation-open");
    toggle.setAttribute("aria-expanded", "true");
    document.body.classList.add("mobile-navigation-open");
    sidebar.querySelector<HTMLAnchorElement>("nav a")?.focus({ preventScroll: true });
  };

  toggle.addEventListener("click", event => {
    event.preventDefault();
    workspace.classList.contains("navigation-open") ? close() : open();
  });
  backdrop.addEventListener("click", close);
  sidebar.querySelectorAll("nav a").forEach(link => link.addEventListener("click", close));
  sidebar.addEventListener("keydown", event => { if (event.key === "Escape") { close(); toggle.focus(); } });
}

function bindSignOut() {
  const button = document.querySelector<HTMLButtonElement>("#logout");
  if (!button) return;
  button.type = "button";
  button.addEventListener("click", async () => {
    if (button.disabled || !confirm("Sign out of IT Connect?")) return;
    button.disabled = true;
    button.setAttribute("aria-busy", "true");
    button.textContent = "Signing out…";
    document.querySelector(".workspace")?.classList.remove("navigation-open");
    document.body.classList.remove("mobile-navigation-open");
    try {
      await presenceCleanup?.();
      presenceCleanup = null;
      await signOut(auth);
      history.replaceState(null, "", "/app/#login");
      renderLogin();
    } catch (error) {
      button.disabled = false;
      button.removeAttribute("aria-busy");
      button.textContent = "Sign out";
      alert(error instanceof Error ? error.message : "Sign out failed. Check your connection and try again.");
    }
  });
}

