async function renderCompanyNotifications(initialTab: "notifications" | "activity" = "notifications") {
  const content = document.querySelector<HTMLElement>(".content")!; const uid = auth.currentUser!.uid;
  content.innerHTML = `<section class="browse-head"><div><span class="eyebrow">Company updates</span><h1>Notifications and activity</h1><p>Review important alerts and your team’s recent operational changes.</p></div><a class="back-link" href="#dashboard">← Overview</a></section><div class="notification-toolbar"><div class="application-tabs"><button data-company-update-tab="notifications">Notifications <span id="notification-count"></span></button><button data-company-update-tab="activity">Activity log</button></div><button id="mark-company-notifications-read">Mark all as read</button></div><div id="company-updates-results"><div class="loading-card">Loading company updates…</div></div>`;
  let tab = initialTab; let notifications: CompanyNotificationRecord[] = []; let activity: Array<{ title: string; detail: string; time: number; kind: string }> = [];
  const paint = () => { document.querySelectorAll<HTMLButtonElement>("[data-company-update-tab]").forEach(button => button.classList.toggle("active", button.dataset.companyUpdateTab === tab)); const unread = notifications.filter(item => !item.read).length; document.querySelector<HTMLElement>("#notification-count")!.textContent = unread ? `(${unread})` : ""; document.querySelector<HTMLButtonElement>("#mark-company-notifications-read")!.hidden = tab !== "notifications" || !unread; const target = document.querySelector<HTMLElement>("#company-updates-results")!; if (tab === "notifications") target.innerHTML = notifications.length ? `<div class="company-notification-list">${notifications.map(item => `<button class="company-notification-row ${item.read ? "" : "unread"}" data-company-notification="${escapeHtml(item.id)}"><span class="notification-symbol">${item.important ? "!" : "○"}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.message)}</p><small>${escapeHtml(item.senderName || item.type.replace(/_/g, " "))} · ${item.createdAt ? new Date(item.createdAt).toLocaleString() : "Recently"}</small></div>${item.read ? "" : `<i></i>`}</button>`).join("")}</div>` : `<div class="empty-card"><strong>No company notifications</strong><p>Administrative and operational alerts will appear here.</p></div>`; else target.innerHTML = activity.length ? `<div class="activity-timeline">${activity.map(item => `<article><span>${item.kind}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.detail)}</p><small>${item.time ? new Date(item.time).toLocaleString() : "Recent activity"}</small></div></article>`).join("")}</div>` : `<div class="empty-card"><strong>No operational activity yet</strong><p>Postings, applications, and training updates will appear here.</p></div>`; document.querySelectorAll<HTMLButtonElement>("[data-company-notification]").forEach(button => button.addEventListener("click", async () => { const item = notifications.find(value => value.id === button.dataset.companyNotification); if (!item) return; if (!item.read) { try { await markCompanyNotificationRead(item.id); item.read = true; paint(); } catch { /* Keep the notification usable even if acknowledgement fails. */ } } const type = item.type.toLowerCase(); if (type.includes("application")) location.hash = "company-applications"; else if (type.includes("message")) location.hash = "messages"; else if (type.includes("internship")) location.hash = "company-opportunities"; })); };
  document.querySelectorAll<HTMLButtonElement>("[data-company-update-tab]").forEach(button => button.addEventListener("click", () => { tab = button.dataset.companyUpdateTab as "notifications" | "activity"; history.replaceState(null, "", `#company-${tab}`); paint(); })); document.querySelector<HTMLButtonElement>("#mark-company-notifications-read")!.addEventListener("click", async event => { const button = event.currentTarget as HTMLButtonElement; button.disabled = true; try { await markAllCompanyNotificationsRead(notifications); notifications.forEach(item => item.read = true); paint(); } catch (error) { alert(error instanceof Error ? error.message : "Notifications could not be updated."); button.disabled = false; } });
  try { const [opportunities, applications, trainees] = await Promise.all([listCompanyOpportunities(uid), listCompanyApplications(uid), listCompanyTrainees(uid)]); activity = [...opportunities.map(item => ({ title: `Opportunity ${item.status}`, detail: item.title, time: item.postedAt, kind: "▣" })), ...applications.map(item => ({ title: `Application ${item.status}`, detail: `${item.studentName} · ${item.internshipTitle}`, time: item.submittedAt, kind: "◷" })), ...trainees.map(item => ({ title: `Training ${item.status}`, detail: `${item.studentName} · ${item.progress}% progress`, time: item.actualStartDate || item.startDate, kind: "✓" }))].sort((a, b) => b.time - a.time); paint(); } catch { activity = []; paint(); }
  const stop = watchCompanyNotifications(uid, items => { notifications = items; paint(); }, error => { if (tab === "notifications") document.querySelector<HTMLElement>("#company-updates-results")!.innerHTML = `<div class="error-card"><strong>Notifications couldn’t be loaded.</strong><p>${escapeHtml(error.message)}</p></div>`; }); routeCleanup = stop;
}

