function openCompanyTrainee(trainee: CompanyTrainee, onUpdated: () => Promise<void>) {
  const dialog = document.createElement("dialog"); dialog.className = "application-detail-modal trainee-modal";
  const action = trainee.status === "accepted" ? `<button class="accept-action" data-trainee-status="active">Start training</button>` : trainee.status === "active" ? `<button class="accept-action" data-trainee-status="completed">Complete training</button><button class="reject-action" data-trainee-status="terminated">End early</button>` : "";
  dialog.innerHTML = `<div class="detail-heading"><div><span class="eyebrow">Training supervision</span><h2>${escapeHtml(trainee.studentName)}</h2><p>${escapeHtml([trainee.role, trainee.department].filter(Boolean).join(" · "))}</p></div><button class="modal-close">×</button></div><div class="trainee-overview"><article><small>Status</small><strong class="status-pill ${escapeHtml(trainee.status)}">${escapeHtml(trainee.status)}</strong></article><article><small>Progress</small><strong>${trainee.progress}%</strong></article><article><small>Supervisors</small><strong>${trainee.supervisorIds.length}</strong></article></div><section class="trainee-update-panel"><span class="eyebrow">Progress update</span><label>Completion percentage<input id="trainee-progress-input" type="range" min="0" max="100" value="${trainee.progress}" ${["completed", "terminated"].includes(trainee.status) ? "disabled" : ""}><output>${trainee.progress}%</output></label><label>Update note<textarea id="trainee-update-note" maxlength="600" placeholder="Record a milestone, performance note, or next step."></textarea></label><div id="trainee-update-status"></div><div class="review-actions"><button class="secondary-action" id="save-trainee-progress" ${["completed", "terminated"].includes(trainee.status) ? "disabled" : ""}>Save progress</button>${action}</div></section><section><span class="eyebrow">Milestones</span><div class="trainee-milestones">${trainee.milestones.length ? trainee.milestones.slice().reverse().map(item => `<article><strong>${escapeHtml(String(item.title || "Progress update"))}</strong><p>${escapeHtml(String(item.note || ""))}</p></article>`).join("") : `<p>No progress updates recorded yet.</p>`}</div></section>`;
  document.body.append(dialog); dialog.querySelector(".modal-close")!.addEventListener("click", () => dialog.close()); dialog.addEventListener("close", () => dialog.remove()); const range = dialog.querySelector<HTMLInputElement>("#trainee-progress-input")!; range.addEventListener("input", () => { dialog.querySelector("output")!.textContent = `${range.value}%`; });
  const save = async (status?: "active" | "completed" | "terminated") => { const note = dialog.querySelector<HTMLTextAreaElement>("#trainee-update-note")!.value.trim(); if (status === "terminated" && !note) return void (dialog.querySelector<HTMLElement>("#trainee-update-status")!.textContent = "Add a reason before ending training early."); if (status && !confirm(`${status === "active" ? "Start" : status === "completed" ? "Complete" : "End"} this training placement?`)) return; dialog.querySelectorAll<HTMLButtonElement>("button").forEach(button => button.disabled = true); try { await updateCompanyTrainee(auth.currentUser!.uid, trainee, { status, progress: status === "completed" ? 100 : Number(range.value), note }); await onUpdated(); dialog.close(); } catch (error) { dialog.querySelector<HTMLElement>("#trainee-update-status")!.textContent = error instanceof Error ? error.message : "Training update could not be saved."; dialog.querySelectorAll<HTMLButtonElement>("button").forEach(button => button.disabled = false); } };
  dialog.querySelector<HTMLButtonElement>("#save-trainee-progress")?.addEventListener("click", () => void save()); dialog.querySelectorAll<HTMLButtonElement>("[data-trainee-status]").forEach(button => button.addEventListener("click", () => void save(button.dataset.traineeStatus as "active" | "completed" | "terminated"))); dialog.showModal();
}

function openCompanyApplicationReview(application: CompanyApplication, policy: CompanyApplicationPolicy, onReviewed: (status: string) => Promise<void>) {
  const dialog = document.createElement("dialog"); dialog.className = "application-detail-modal company-review-modal";
  const date = (value: string | number) => value && !Number.isNaN(new Date(value).getTime()) ? new Date(value).toLocaleDateString() : "Not specified";
  dialog.innerHTML = `<div class="detail-heading"><div><span class="eyebrow">${escapeHtml(application.internshipTitle)}</span><h2>${escapeHtml(application.studentName)}</h2><p>${escapeHtml([application.course, application.institution, application.level].filter(Boolean).join(" · ") || "Student profile")}</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="detail-status"><div><small>Current status</small><strong class="status-pill ${escapeHtml(application.status)}">${escapeHtml(application.status)}</strong></div><div><small>Submitted</small><strong>${date(application.submittedAt)}</strong></div><div><small>Preferred start</small><strong>${date(application.startDate)}</strong></div><div><small>Duration</small><strong>${escapeHtml(application.selectedDuration || "Not specified")}</strong></div></div><div class="detail-columns"><section><span class="eyebrow">Application statement</span><p>${escapeHtml(application.description || "No statement was provided.")}</p><span class="eyebrow detail-label">Documents</span><div class="detail-documents">${application.documents.length ? application.documents.map(file => `<a href="${escapeHtml(file.url)}" target="_blank" rel="noopener"><span>↗</span><div><strong>${escapeHtml(file.name)}</strong><small>Open document</small></div></a>`).join("") : `<p>No documents are attached.</p>`}</div></section><section><span class="eyebrow">Student contact</span><div class="review-contact"><div><small>Email</small><strong>${escapeHtml(application.email || "Not provided")}</strong></div><div><small>Phone</small><strong>${escapeHtml(application.phone || "Not provided")}</strong></div></div><label class="review-note">Decision note<textarea id="company-review-note" maxlength="600" placeholder="Add feedback or next steps for the student.">${escapeHtml(application.rejectionReason)}</textarea></label><div id="company-review-status"></div><div class="review-actions"><button data-review-decision="rejected" class="reject-action" ${application.status !== "pending" ? "disabled" : ""}>Not selected</button><button data-review-decision="accepted" class="accept-action" ${application.status !== "pending" ? "disabled" : ""}>Accept application</button></div>${application.status !== "pending" ? `<p class="review-complete">This application has already been reviewed.</p>` : ""}</section></div>`;
  document.body.append(dialog); dialog.querySelector(".modal-close")!.addEventListener("click", () => dialog.close()); dialog.addEventListener("close", () => dialog.remove());
  const acceptButton = dialog.querySelector<HTMLButtonElement>('[data-review-decision="accepted"]'); const rejectButton = dialog.querySelector<HTMLButtonElement>('[data-review-decision="rejected"]');
  if (acceptButton && !policy.companyCanAccept) { acceptButton.disabled = true; acceptButton.title = policy.reason || "Acceptance is controlled by your authority."; }
  if (rejectButton && !policy.companyCanReject) { rejectButton.disabled = true; rejectButton.title = policy.reason || "Rejection is controlled by your authority."; }
  dialog.querySelectorAll<HTMLButtonElement>("[data-review-decision]").forEach(button => button.addEventListener("click", async () => { const decision = button.dataset.reviewDecision as "accepted" | "rejected"; const note = dialog.querySelector<HTMLTextAreaElement>("#company-review-note")!.value.trim(); if (decision === "rejected" && !note) { dialog.querySelector<HTMLElement>("#company-review-status")!.textContent = "Add a short reason before declining this application."; return; } if (!confirm(`${decision === "accepted" ? "Accept" : "Decline"} ${application.studentName} for this opportunity?`)) return; dialog.querySelectorAll<HTMLButtonElement>("[data-review-decision]").forEach(item => item.disabled = true); try { const finalStatus = await reviewCompanyApplication(auth.currentUser!.uid, application, decision, note); await onReviewed(finalStatus); dialog.close(); } catch (error) { dialog.querySelector<HTMLElement>("#company-review-status")!.textContent = error instanceof Error ? error.message : "The decision could not be saved."; dialog.querySelectorAll<HTMLButtonElement>("[data-review-decision]").forEach(item => item.disabled = false); } })); dialog.showModal();
}

