function paintInternships() {
  const search = document.querySelector<HTMLInputElement>("#it-search")!.value;
  const category = document.querySelector<HTMLSelectElement>("#it-category")!.value;
  const state = document.querySelector<HTMLSelectElement>("#it-state")!.value;
  const paid = document.querySelector<HTMLInputElement>("#it-paid")!.checked;
  const filtered = internshipCache.filter(item => !item.removed && matchesInternship(item, search, category, state, paid));
  const localState = currentProfile?.state?.toLowerCase();
  const local = localState ? filtered.filter(item => item.state.toLowerCase() === localState) : [];
  const other = localState ? filtered.filter(item => item.state.toLowerCase() !== localState) : filtered;
  const card = (item: Internship) => `<article class="it-card" data-id="${escapeHtml(item.id)}"><div class="company-row"><div class="company-logo">${item.companyLogo ? `<img src="${escapeHtml(item.companyLogo)}" alt="">` : escapeHtml(item.companyName.slice(0,1))}</div><div><span>${escapeHtml(item.companyName)}</span><small>${escapeHtml([item.state,item.lga].filter(Boolean).join(", ") || "Location not specified")}</small></div><button class="save ${savedIds.has(item.id) ? "saved" : ""}" data-save="${escapeHtml(item.id)}" aria-label="Save opportunity">♡</button></div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.description || "View the full opportunity details and requirements.")}</p><div class="chips"><span>${escapeHtml(item.industry || item.course || "General")}</span><span>${escapeHtml(item.duration)}</span><span class="${item.paid ? "paid" : ""}">${item.paid ? `₦${(item.stipend || 0).toLocaleString()}` : "Unpaid"}</span></div><button class="view" data-view="${escapeHtml(item.id)}">View opportunity →</button></article>`;
  const section = (title: string, items: Internship[]) => items.length ? `<section class="result-group"><div class="result-title"><h2>${title}</h2><span>${items.length} found</span></div><div class="it-grid">${items.map(card).join("")}</div></section>` : "";
  document.querySelector<HTMLElement>("#it-results")!.innerHTML = filtered.length ? `${section("Opportunities in your state", local)}${section(local.length ? "Other opportunities" : "Available opportunities", other)}` : `<div class="empty-card"><strong>No matching opportunities</strong><p>Try clearing a filter or searching with a broader course or skill.</p></div>`;
  document.querySelectorAll<HTMLButtonElement>("[data-view]").forEach(button => button.addEventListener("click", () => showInternship(button.dataset.view!)));
  document.querySelectorAll<HTMLButtonElement>("[data-save]").forEach(button => button.addEventListener("click", async () => { const item = internshipCache.find(value => value.id === button.dataset.save); if (!item || !auth.currentUser || currentProfile?.role !== "student") return; button.disabled = true; const wasSaved = savedIds.has(item.id); try { await toggleSaved(auth.currentUser.uid, item, wasSaved); wasSaved ? savedIds.delete(item.id) : savedIds.add(item.id); paintInternships(); } finally { button.disabled = false; } }));
}

function showInternship(id: string) {
  const item = internshipCache.find(value => value.id === id); if (!item) return;
  if (auth.currentUser) recordRecentInternship(auth.currentUser.uid, item.id);
  const modal = document.createElement("dialog"); modal.className = "it-modal";
  modal.innerHTML = `<button class="modal-close" aria-label="Close">×</button><span class="eyebrow">${escapeHtml(item.companyName)}</span><h2>${escapeHtml(item.title)}</h2><p class="location">${escapeHtml([item.address,item.state,item.lga].filter(Boolean).join(", ") || "Location not specified")}</p><div class="detail-grid"><div><small>Duration</small><strong>${escapeHtml(item.duration)}</strong></div><div><small>Compensation</small><strong>${item.paid ? `₦${(item.stipend || 0).toLocaleString()}` : "Unpaid"}</strong></div><div><small>Category</small><strong>${escapeHtml(item.industry || item.course || "General")}</strong></div></div><h3>About this opportunity</h3><p>${escapeHtml(item.description || "No additional description has been provided.")}</p><div class="modal-actions"><button class="primary" ${item.removed ? "disabled" : ""}>${item.removed ? "Opportunity removed" : "Start application"}</button></div>`;
  document.body.append(modal); modal.querySelector(".modal-close")!.addEventListener("click", () => modal.close()); modal.querySelector<HTMLButtonElement>(".modal-actions .primary")?.addEventListener("click", () => { modal.close(); void showApplicationForm(item); }); modal.addEventListener("close", () => modal.remove()); modal.showModal();
}

async function showApplicationForm(item: Internship) {
  if (currentProfile?.role !== "student") return alert("Applications are available from student accounts.");
  let slotBalance = 0;
  try { const profile = await getStudentProfile(auth.currentUser!.uid); const missing = [["institution", profile.institution], ["course of study", profile.courseOfStudy], ["student registration number", profile.registrationNumber], ["matric number", profile.matricNumber]].filter(([, value]) => !String(value || "").trim()).map(([label]) => label); if (missing.length) { alert(`Complete your student onboarding before applying. Missing: ${missing.join(", ")}.`); location.hash = "profile"; return; } slotBalance = Number(profile.slotBalance || 0); if (!Number.isInteger(slotBalance) || slotBalance < 1) { alert("One application slot is required. Purchase slots before applying."); location.hash = "wallet"; return; } } catch (error) { alert(error instanceof Error ? error.message : "Complete your student profile before applying."); location.hash = "profile"; return; }
  const draftKey = `itc-application-draft:${item.id}`;
  const savedDraft = JSON.parse(localStorage.getItem(draftKey) || "{}") as Record<string, string>;
  const modal = document.createElement("dialog"); modal.className = "application-modal";
  modal.innerHTML = `<form id="application-form"><div class="form-heading"><div><span class="eyebrow">Application draft</span><h2>${escapeHtml(item.title)}</h2><p>${escapeHtml(item.companyName)}</p></div><button type="button" class="modal-close">×</button></div><div class="step-note"><b>1</b> Training details <span></span><b>2</b> Documents <span></span><b>3</b> Confirm</div><label>Training description<textarea id="apply-description" minlength="40" maxlength="1500" required placeholder="Explain your training goals, relevant skills, and what you hope to learn.">${escapeHtml(savedDraft.description || "")}</textarea><small>Minimum 40 characters</small></label><div class="form-row"><label>Preferred start date<input id="apply-start" type="date" value="${escapeHtml(savedDraft.startDate || "")}"></label><label>Preferred end date<input id="apply-end" type="date" value="${escapeHtml(savedDraft.endDate || "")}"></label></div><label>Duration<select id="apply-duration" required><option value="">Select duration</option>${["3 months","4 months","6 months","9 months","12 months"].map(value => `<option ${savedDraft.duration === value ? "selected" : ""}>${value}</option>`).join("")}</select></label><fieldset><legend>Supporting documents</legend><p>PDF, JPG, or PNG; maximum 10 MB each. Resume and IT letter are required.</p><div class="upload-grid"><label>Resume <em>Required</em><input data-kind="resume" type="file" accept=".pdf,.jpg,.jpeg,.png" required></label><label>IT letter <em>Required</em><input data-kind="itLetter" type="file" accept=".pdf,.jpg,.jpeg,.png" required></label><label>Student ID card<input data-kind="idCard" type="file" accept=".pdf,.jpg,.jpeg,.png"></label><label>Cover letter<input data-kind="coverLetter" type="file" accept=".pdf,.jpg,.jpeg,.png"></label></div></fieldset><label class="consent"><input id="apply-confirm" type="checkbox" required> I confirm that this information and the uploaded documents are accurate.</label><div id="application-status" role="status"></div><div class="form-actions"><button type="button" class="secondary" id="save-draft">Save draft</button><button class="primary" type="submit">Review and submit</button></div></form>`;
  modal.querySelector(".step-note")?.insertAdjacentHTML("afterend", `<div class="detail-notice"><strong>One application slot</strong><span>You have ${slotBalance.toLocaleString()} slot${slotBalance === 1 ? "" : "s"}. One slot is deducted securely only when submission succeeds.</span></div>`);
  document.body.append(modal); modal.querySelector(".modal-close")!.addEventListener("click", () => modal.close()); modal.addEventListener("close", () => modal.remove());
  const capture = () => ({ description: modal.querySelector<HTMLTextAreaElement>("#apply-description")!.value, startDate: modal.querySelector<HTMLInputElement>("#apply-start")!.value, endDate: modal.querySelector<HTMLInputElement>("#apply-end")!.value, duration: modal.querySelector<HTMLSelectElement>("#apply-duration")!.value });
  modal.querySelector("#save-draft")!.addEventListener("click", () => { localStorage.setItem(draftKey, JSON.stringify(capture())); modal.querySelector<HTMLElement>("#application-status")!.textContent = "Draft saved on this device."; });
  modal.querySelector<HTMLFormElement>("#application-form")!.addEventListener("submit", async event => { event.preventDefault(); const status = modal.querySelector<HTMLElement>("#application-status")!; const submit = modal.querySelector<HTMLButtonElement>('button[type="submit"]')!; const values = capture(); if (values.startDate && values.endDate && new Date(values.endDate) <= new Date(values.startDate)) return void (status.textContent = "End date must be after the start date."); const files = [...modal.querySelectorAll<HTMLInputElement>('input[type="file"]')].flatMap(input => input.files?.[0] ? [{ kind: input.dataset.kind || "other", file: input.files[0] }] : []); submit.disabled = true; submit.textContent = "Uploading and submitting…"; status.textContent = "Keep this window open while your documents upload."; try { await submitApplication(auth.currentUser!.uid, item, { description: values.description, startDate: values.startDate, endDate: values.endDate, selectedDuration: values.duration, files }); localStorage.removeItem(draftKey); modal.innerHTML = `<div class="application-success"><span>✓</span><h2>Application submitted</h2><p>${escapeHtml(item.companyName)} can now review your application. You can follow every update from My Applications.</p><button class="primary">View my applications</button></div>`; modal.querySelector("button")!.addEventListener("click", () => { modal.close(); location.hash = "applications"; }); } catch (error) { status.textContent = error instanceof Error ? error.message : "Submission failed."; submit.disabled = false; submit.textContent = "Review and submit"; } });
  modal.showModal();
}

