  dialog.querySelector<HTMLButtonElement>("#message-directory-company")?.addEventListener("click", () => { sessionStorage.setItem("itc-message-target", JSON.stringify({uid: company.id, name: company.name, username: company.username, imageUrl: company.logoUrl, role: "company"})); dialog.close(); location.hash = "messages"; }); dialog.showModal();
