async function renderMessages() {
  const content = document.querySelector<HTMLElement>(".content")!; const uid = auth.currentUser!.uid;
  content.innerHTML = `<section class="browse-head"><div><span class="eyebrow">Direct messages</span><h1>Conversations</h1><p>Messages shared across students, companies and authorities.</p></div><a class="back-link" href="#dashboard">← Dashboard</a></section><div class="messages-layout"><aside class="conversation-panel"><label class="conversation-search">⌕<input id="conversation-search" placeholder="Search conversations"></label><div id="conversation-list"><div class="loading-card">Loading conversations…</div></div></aside><section class="chat-panel" id="chat-panel"><div class="chat-empty"><span>✉</span><strong>Select a conversation</strong><p>Your messages will appear here.</p></div></section></div>`;
  let rooms: ChatRoom[] = []; let selectedRoom = ""; let stopMessages: (() => void) | null = null; let stopContactPresence: (() => void) | null = null; let search = ""; let pendingTarget: ChatRoom["contact"] | null = null;
  try { const stored = sessionStorage.getItem("itc-message-target"); if (stored) pendingTarget = JSON.parse(stored) as ChatRoom["contact"]; } catch { sessionStorage.removeItem("itc-message-target"); }
  const paintRooms = () => { const visible = rooms.filter(room => `${room.contact.name} ${room.contact.username} ${room.preview}`.toLowerCase().includes(search.toLowerCase())); document.querySelector<HTMLElement>("#conversation-list")!.innerHTML = visible.length ? visible.map(room => `<button class="conversation-row ${selectedRoom === room.id ? "active" : ""}" data-room="${escapeHtml(room.id)}"><div class="community-avatar">${room.contact.imageUrl ? `<img src="${escapeHtml(room.contact.imageUrl)}" alt="">` : escapeHtml(room.contact.name.slice(0, 1))}</div><div><strong>${escapeHtml(room.contact.name)}</strong><span>${room.contact.username ? `@${escapeHtml(room.contact.username)}` : escapeHtml(room.contact.role)}</span><p>${escapeHtml(room.preview)}</p></div><aside><small>${room.updatedAt ? new Date(room.updatedAt).toLocaleDateString() : ""}</small>${room.unread ? `<b>${room.unread}</b>` : ""}</aside></button>`).join("") : `<div class="conversation-empty"><strong>No conversations</strong><p>Your existing chats will appear here.</p></div>`; document.querySelectorAll<HTMLButtonElement>("[data-room]").forEach(button => button.addEventListener("click", () => { const room = rooms.find(item => item.id === button.dataset.room); if (room) openRoom(room); })); };
  const openRoom = (room: ChatRoom) => {
    selectedRoom = room.id; paintRooms(); stopMessages?.(); stopContactPresence?.();
    const panel = document.querySelector<HTMLElement>("#chat-panel")!;
    panel.innerHTML = `<header class="chat-heading"><div class="community-avatar">${room.contact.imageUrl ? `<img src="${escapeHtml(room.contact.imageUrl)}" alt="">` : escapeHtml(room.contact.name.slice(0, 1))}</div><div><strong>${escapeHtml(room.contact.name)}</strong><span>${room.contact.username ? `@${escapeHtml(room.contact.username)} · ` : ""}<span class="chat-presence" id="chat-presence">Checking status…</span></span></div></header><div class="message-stream" id="message-stream"><div class="loading-card">Loading messages…</div></div><form class="message-composer" id="message-form"><textarea id="message-content" rows="1" maxlength="5000" required placeholder="Write a message…"></textarea><button type="submit">Send</button></form><div id="message-status"></div>`;
    stopContactPresence = watchPresence(room.contact.uid, presence => {
      const indicator = panel.querySelector<HTMLElement>("#chat-presence");
      if (!indicator) return;
      indicator.classList.toggle("online", presence.online);
      indicator.textContent = presence.online ? "Online" : presence.lastSeen ? `Last seen ${new Date(presence.lastSeen).toLocaleString()}` : "Offline";
    });
    stopMessages = watchMessages(room.roomIds, uid, messages => { const stream = panel.querySelector<HTMLElement>("#message-stream")!; stream.innerHTML = messages.length ? messages.map(message => `<article class="message-bubble ${message.senderId === uid ? "mine" : "theirs"}"><p>${renderPostText(message.content)}</p><small>${message.timestamp ? new Date(message.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) : "Sending…"}${message.senderId === uid ? message.isRead ? " · Read" : message.isDelivered ? " · Delivered" : " · Sent" : ""}</small></article>`).join("") : `<div class="chat-empty"><strong>Start the conversation</strong><p>Send a message to ${escapeHtml(room.contact.name)}.</p></div>`; stream.scrollTop = stream.scrollHeight; }, error => { panel.querySelector<HTMLElement>("#message-stream")!.innerHTML = `<div class="error-card"><strong>Messages couldn’t be loaded.</strong><p>${escapeHtml(error.message)}</p></div>`; });
    panel.querySelector<HTMLFormElement>("#message-form")!.addEventListener("submit", async event => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; const input = form.querySelector<HTMLTextAreaElement>("#message-content")!; const button = form.querySelector<HTMLButtonElement>("button")!; const value = input.value.trim(); if (!value) return; button.disabled = true; try { await sendTextMessage(uid, room.contact.uid, value, room.id); input.value = ""; } catch (error) { panel.querySelector<HTMLElement>("#message-status")!.textContent = error instanceof Error ? error.message : "Message could not be sent."; } finally { button.disabled = false; input.focus(); } });
  };
  document.querySelector<HTMLInputElement>("#conversation-search")!.addEventListener("input", event => { search = (event.currentTarget as HTMLInputElement).value; paintRooms(); });
  const stopRooms = watchChatRooms(uid, value => { rooms = value; if (pendingTarget) { let targetRoom = rooms.find(room => room.contact.uid === pendingTarget!.uid); if (!targetRoom) { const id = directRoomId(uid, pendingTarget.uid); targetRoom = {id, roomIds: [id], contact: pendingTarget, preview: "Start a conversation", updatedAt: 0, unread: 0}; rooms = [targetRoom, ...rooms]; } sessionStorage.removeItem("itc-message-target"); pendingTarget = null; paintRooms(); openRoom(targetRoom); return; } paintRooms(); if (selectedRoom) { const refreshed = rooms.find(room => room.id === selectedRoom); if (!refreshed) { selectedRoom = ""; stopMessages?.(); stopMessages = null; } } }, error => { document.querySelector<HTMLElement>("#conversation-list")!.innerHTML = `<div class="error-card"><strong>Conversations couldn’t be loaded.</strong><p>${escapeHtml(error.message)}</p></div>`; });
  routeCleanup = () => { stopRooms(); stopMessages?.(); stopContactPresence?.(); };
}

async function renderCommunity() {
  const content = document.querySelector<HTMLElement>(".content")!;
  content.innerHTML = `<section class="browse-head"><div><span class="eyebrow">Professional community</span><h1>Learn, share and connect.</h1><p>Updates from students, companies and authorities across IT Connect.</p></div><a class="back-link" href="#dashboard">← Dashboard</a></section><section class="community-compose"><div class="avatar">${escapeHtml(currentProfile?.name.slice(0, 1).toUpperCase() || "I")}</div><form id="community-form"><textarea id="post-content" minlength="3" maxlength="5000" required placeholder="Share an experience, question or opportunity… Use @username and #hashtags."></textarea><div id="post-preview"></div><div class="compose-actions"><label>＋ Add photo<input id="post-image" type="file" accept="image/*"></label><span id="post-status"></span><button class="primary" type="submit">Publish post</button></div></form></section><section class="community-controls"><div><button class="active" data-feed="all">All posts</button><button data-feed="following">Following</button><button data-feed="saved">Saved posts</button></div><label>⌕<input id="community-search" placeholder="Search posts or #hashtags"></label><button id="clear-community-filter" hidden>Clear filter</button></section><div id="community-feed"><div class="loading-card">Loading community…</div></div>`;
  if (currentProfile) hydrateGlobalAvatar(currentProfile, ".community-compose .avatar");
  let previewUrl = ""; let posts: CommunityPost[] = []; let following = new Set<string>(); let savedPosts = new Set<string>(); let scope: "all" | "following" | "saved" = "all"; let filter = "";
  const hiddenStorageKey = `itc-hidden-community-posts:${auth.currentUser!.uid}`;
  let hiddenPosts = new Set<string>();
  try { const stored = JSON.parse(localStorage.getItem(hiddenStorageKey) || "[]"); if (Array.isArray(stored)) hiddenPosts = new Set(stored.filter((id): id is string => typeof id === "string")); } catch { localStorage.removeItem(hiddenStorageKey); }
  const paint = () => {
    const needle = filter.trim().toLowerCase().replace(/^#/, "");
    const visible = posts.filter(post => !hiddenPosts.has(post.id) && (scope === "all" || scope === "saved" && savedPosts.has(post.id) || scope === "following" && (following.has(post.authorUid) || post.authorUid === auth.currentUser!.uid)) && (!needle || `${post.content} ${post.authorName} ${post.username} ${post.hashtags.join(" ")}`.toLowerCase().includes(needle)));
    document.querySelector<HTMLButtonElement>("#clear-community-filter")!.hidden = !needle;
    document.querySelector<HTMLElement>("#community-feed")!.innerHTML = visible.length ? `<div class="community-list">${visible.map(post => communityPostCard(post, auth.currentUser!.uid, savedPosts.has(post.id))).join("")}</div>` : `<div class="empty-card"><strong>No community posts found</strong><p>${scope === "following" ? "Follow members to build your personal feed, or switch back to all posts." : scope === "saved" ? "Posts you save will appear here." : "Be the first to start this conversation."}</p></div>`;
    document.querySelectorAll<HTMLButtonElement>("[data-hashtag]").forEach(button => button.addEventListener("click", () => { filter = button.dataset.hashtag || ""; document.querySelector<HTMLInputElement>("#community-search")!.value = `#${filter}`; paint(); }));
    document.querySelectorAll<HTMLButtonElement>("[data-delete-post]").forEach(button => button.addEventListener("click", async () => { const post = posts.find(item => `${item.source}/${item.id}` === button.dataset.deletePost); if (!post || !confirm("Delete this community post and its attached image?")) return; button.disabled = true; try { await deleteCommunityPost(auth.currentUser!.uid, post); posts = posts.filter(item => item !== post); paint(); } catch (error) { button.disabled = false; alert(error instanceof Error ? error.message : "The post could not be deleted."); } }));
    document.querySelectorAll<HTMLButtonElement>("[data-open-post]").forEach(button => button.addEventListener("click", () => { const post = posts.find(item => item.id === button.dataset.openPost); if (post) openCommunityPost(post, paint); }));
    document.querySelectorAll<HTMLButtonElement>("[data-community-profile]").forEach(button => button.addEventListener("click", () => { const post = posts.find(item => item.authorUid === button.dataset.communityProfile); if (post) void openCommunityMemberProfile(post.authorUid, post.authorRole, post.authorName, post.authorImage, posts.filter(item => item.authorUid === post.authorUid)); }));
    document.querySelectorAll<HTMLButtonElement>("[data-edit-post]").forEach(button => button.addEventListener("click", async () => { const post = posts.find(item => item.id === button.dataset.editPost); if (!post) return; const content = prompt("Edit your post", post.content); if (!content?.trim() || content.trim() === post.content) return; button.disabled = true; try { await updateCommunityPost(auth.currentUser!.uid, post, content); post.content = content.trim(); post.hashtags = [...post.content.matchAll(/#([\w-]+)/g)].map(match => match[1].toLowerCase()); paint(); } catch (error) { button.disabled = false; alert(error instanceof Error ? error.message : "The post could not be updated."); } }));
    document.querySelectorAll<HTMLButtonElement>("[data-react-post]").forEach(button => button.addEventListener("click", async () => { const post = posts.find(item => item.id === button.dataset.reactPost); if (!post) return; const current = post.reactions[auth.currentUser!.uid] || (post.likes.includes(auth.currentUser!.uid) ? "like" : ""); const reaction = current ? null : "like"; button.disabled = true; try { await setPostReaction(auth.currentUser!.uid, post.id, reaction); if (reaction) { post.reactions[auth.currentUser!.uid] = reaction; if (!post.likes.includes(auth.currentUser!.uid)) post.likes.push(auth.currentUser!.uid); } else { delete post.reactions[auth.currentUser!.uid]; post.likes = post.likes.filter(id => id !== auth.currentUser!.uid); } paint(); } catch (error) { button.disabled = false; alert(error instanceof Error ? error.message : "Reaction could not be saved."); } }));
    document.querySelectorAll<HTMLButtonElement>("[data-save-post]").forEach(button => button.addEventListener("click", async () => { const id = button.dataset.savePost!; const saved = savedPosts.has(id); button.disabled = true; try { await toggleSavedPost(auth.currentUser!.uid, id, saved); saved ? savedPosts.delete(id) : savedPosts.add(id); paint(); } catch (error) { button.disabled = false; alert(error instanceof Error ? error.message : "Post could not be saved."); } }));
    document.querySelectorAll<HTMLButtonElement>("[data-share-post]").forEach(button => button.addEventListener("click", async () => { const post = posts.find(item => item.id === button.dataset.sharePost); if (!post) return; const url = `${location.origin}${location.pathname}#community`; try { if (navigator.share) await navigator.share({ title: `${post.authorName} on IT Connect`, text: post.content, url }); else { await navigator.clipboard.writeText(`${post.content}\n${url}`); button.textContent = "Copied"; } if (await recordPostShare(auth.currentUser!.uid, post.id)) post.shareCount += 1; paint(); } catch { /* The user can cancel the native share sheet. */ } }));
    document.querySelectorAll<HTMLButtonElement>("[data-copy-post]").forEach(button => button.addEventListener("click", async () => { const post = posts.find(item => item.id === button.dataset.copyPost); if (!post) return; const url = `${location.origin}${location.pathname}#community`; try { await navigator.clipboard.writeText(`${post.content}\n${url}`); button.textContent = "Copied"; } catch { alert("The post could not be copied. Please allow clipboard access and try again."); } }));
    document.querySelectorAll<HTMLButtonElement>("[data-hide-post]").forEach(button => button.addEventListener("click", () => { const id = button.dataset.hidePost; if (!id) return; hiddenPosts.add(id); localStorage.setItem(hiddenStorageKey, JSON.stringify([...hiddenPosts])); paint(); }));
    document.querySelectorAll<HTMLButtonElement>("[data-report-post]").forEach(button => button.addEventListener("click", async () => { const post = posts.find(item => item.id === button.dataset.reportPost); if (!post) return; const reason = prompt("Why are you reporting this post?", "Spam or inappropriate content"); if (!reason?.trim()) return; button.disabled = true; try { await reportCommunityPost(auth.currentUser!.uid, post, reason); button.textContent = "Reported"; } catch (error) { button.disabled = false; alert(error instanceof Error ? error.message : "Report could not be submitted."); } }));
  };
  try { [posts, following, savedPosts] = await Promise.all([listCommunityPosts(), getFollowingIds(auth.currentUser!.uid), getSavedPostIds(auth.currentUser!.uid)]); paint(); } catch (error) { document.querySelector<HTMLElement>("#community-feed")!.innerHTML = `<div class="error-card"><strong>We couldn’t load the community.</strong><p>${escapeHtml(error instanceof Error ? error.message : "Please try again.")}</p></div>`; }
  document.querySelectorAll<HTMLButtonElement>("[data-feed]").forEach(button => button.addEventListener("click", () => { scope = button.dataset.feed as "all" | "following" | "saved"; document.querySelectorAll("[data-feed]").forEach(value => value.classList.remove("active")); button.classList.add("active"); paint(); }));
  document.querySelector<HTMLInputElement>("#community-search")!.addEventListener("input", event => { filter = (event.currentTarget as HTMLInputElement).value; paint(); });
  document.querySelector<HTMLButtonElement>("#clear-community-filter")!.addEventListener("click", () => { filter = ""; document.querySelector<HTMLInputElement>("#community-search")!.value = ""; paint(); });
  document.querySelector<HTMLInputElement>("#post-image")!.addEventListener("change", event => { const input = event.currentTarget as HTMLInputElement; if (previewUrl) URL.revokeObjectURL(previewUrl); const file = input.files?.[0]; previewUrl = file ? URL.createObjectURL(file) : ""; document.querySelector<HTMLElement>("#post-preview")!.innerHTML = previewUrl ? `<img src="${previewUrl}" alt="Post image preview"><button type="button" id="remove-post-image">Remove image</button>` : ""; document.querySelector<HTMLButtonElement>("#remove-post-image")?.addEventListener("click", () => { input.value = ""; URL.revokeObjectURL(previewUrl); previewUrl = ""; document.querySelector<HTMLElement>("#post-preview")!.innerHTML = ""; }); });
  document.querySelector<HTMLFormElement>("#community-form")!.addEventListener("submit", async event => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; const submit = form.querySelector<HTMLButtonElement>('button[type="submit"]')!; const status = document.querySelector<HTMLElement>("#post-status")!; const text = document.querySelector<HTMLTextAreaElement>("#post-content")!.value.trim(); const image = document.querySelector<HTMLInputElement>("#post-image")!.files?.[0]; submit.disabled = true; submit.textContent = image ? "Uploading…" : "Publishing…"; try { await createCommunityPost(auth.currentUser!.uid, currentProfile!, text, image); form.reset(); if (previewUrl) URL.revokeObjectURL(previewUrl); previewUrl = ""; document.querySelector<HTMLElement>("#post-preview")!.innerHTML = ""; status.textContent = "Post published."; posts = await listCommunityPosts(); paint(); } catch (error) { status.textContent = error instanceof Error ? error.message : "The post could not be published."; } finally { submit.disabled = false; submit.textContent = "Publish post"; } });
}

function renderPostText(value: string): string {
  return escapeHtml(value).replace(/(^|\s)(#[\w-]+)/g, '$1<span class="inline-hashtag">$2</span>').replace(/(^|\s)(@[\w.-]+)/g, '$1<span class="inline-mention">$2</span>').replace(/\n/g, "<br>");
}

function canManageCommunityPost(post: CommunityPost, uid: string): boolean {
  return post.authorUid === uid;
}

function communityPostCard(post: CommunityPost, uid: string, saved: boolean): string {
  const selected = post.reactions[uid] || (post.likes.includes(uid) ? "like" : ""); const total = new Set([...Object.keys(post.reactions), ...post.likes]).size;
  const ownershipActions = canManageCommunityPost(post, uid)
    ? `<details class="post-options"><summary aria-label="Post options">⋯</summary><div><button data-edit-post="${escapeHtml(post.id)}">Edit post</button><button data-copy-post="${escapeHtml(post.id)}">Copy post & link</button><button class="danger" data-delete-post="${escapeHtml(post.source)}/${escapeHtml(post.id)}">Delete post</button></div></details>`
    : `<details class="post-options"><summary aria-label="Post options">⋯</summary><div><button data-copy-post="${escapeHtml(post.id)}">Copy post & link</button><button data-hide-post="${escapeHtml(post.id)}">Hide this post</button><button class="danger" data-report-post="${escapeHtml(post.id)}">Report post</button></div></details>`;
  const latestComment = post.latestComment ? `<button class="latest-comment" data-open-post="${escapeHtml(post.id)}"><strong>${escapeHtml(post.latestComment.userName)}</strong><span>${renderPostText(post.latestComment.content)}</span></button>` : "";
  return `<article class="community-post"><header><button class="community-author" data-community-profile="${escapeHtml(post.authorUid)}"><span class="community-avatar">${post.authorImage ? `<img src="${escapeHtml(post.authorImage)}" alt="">` : escapeHtml(post.authorName.slice(0, 1))}</span><span><strong>${escapeHtml(post.authorName)}</strong><small>${post.username ? `@${escapeHtml(post.username)}` : escapeHtml(post.authorRole)} · ${post.createdAt ? new Date(post.createdAt).toLocaleDateString() : "Just now"}</small></span></button>${ownershipActions}</header><button class="post-content-button" data-open-post="${escapeHtml(post.id)}"><span>${renderPostText(post.content)}</span>${post.imageUrl ? `<img class="post-image" src="${escapeHtml(post.imageUrl)}" alt="Post attachment">` : ""}</button>${post.hashtags.length ? `<footer>${post.hashtags.map(tag => `<button data-hashtag="${escapeHtml(tag)}">#${escapeHtml(tag)}</button>`).join("")}</footer>` : ""}<div class="engagement-summary"><span>${total} like${total === 1 ? "" : "s"}</span><button data-open-post="${escapeHtml(post.id)}">${post.commentCount} comment${post.commentCount === 1 ? "" : "s"}</button><span>${post.shareCount} share${post.shareCount === 1 ? "" : "s"}</span></div>${latestComment}<div class="post-interactions"><button class="${selected ? "selected" : ""}" data-react-post="${escapeHtml(post.id)}">${selected ? `✓ ${escapeHtml(selected)}` : "♡ Like"}</button><button data-open-post="${escapeHtml(post.id)}">◯ Comment</button><button class="${saved ? "selected" : ""}" data-save-post="${escapeHtml(post.id)}">${saved ? "★ Saved" : "☆ Save"}</button><button data-share-post="${escapeHtml(post.id)}">↗ Share</button></div></article>`;
}

async function openCommunityMemberProfile(uid: string, roleHint: string, fallbackName: string, fallbackImage: string, knownPosts?: CommunityPost[]) {
  const dialog = document.createElement("dialog"); dialog.className = "community-profile-modal";
  dialog.innerHTML = `<button class="modal-close" aria-label="Close">×</button><div class="loading-card">Loading profile…</div>`;
  document.body.append(dialog); dialog.querySelector(".modal-close")!.addEventListener("click", () => dialog.close()); dialog.addEventListener("click", event => { if (event.target === dialog) dialog.close(); }); dialog.addEventListener("close", () => dialog.remove()); dialog.showModal();
  try {
    const [profile, memberPosts] = await Promise.all([getCommunityMemberProfile(uid, roleHint), knownPosts ? Promise.resolve(knownPosts) : listCommunityPosts().then(items => items.filter(item => item.authorUid === uid))]);
    const name = profile.name === "IT Connect member" ? fallbackName : profile.name;
    const adminFallback = profile.role.includes("admin") || name.toLowerCase() === "it connect" ? "/app/images/appstore.png" : "";
    const image = profile.imageUrl || fallbackImage || adminFallback;
    const details = profile.role === "student" ? [profile.organisation, profile.category, profile.level && `Level ${profile.level}`, profile.state] : [profile.category, profile.state, profile.address];
    const links = [["Website", profile.website], ["LinkedIn", profile.linkedinUrl], ["GitHub", profile.githubUrl], ["Portfolio", profile.portfolioUrl]].filter(([, url]) => url);
    const timeline = memberPosts.length ? memberPosts.map(item => { const reactions = new Set([...Object.keys(item.reactions), ...item.likes]).size; return `<button class="profile-timeline-post" data-profile-post="${escapeHtml(item.id)}"><small>${item.createdAt ? new Date(item.createdAt).toLocaleString() : "Recently"}</small><p>${renderPostText(item.content)}</p>${item.imageUrl ? `<img src="${escapeHtml(item.imageUrl)}" alt="Post attachment">` : ""}<span>${reactions} like${reactions === 1 ? "" : "s"} · ${item.commentCount} comment${item.commentCount === 1 ? "" : "s"} · ${item.shareCount} share${item.shareCount === 1 ? "" : "s"}</span></button>`; }).join("") : `<div class="empty-card"><strong>No posts yet</strong><p>Posts shared by this member will appear here.</p></div>`;
    dialog.innerHTML = `<button class="modal-close" aria-label="Close">×</button><section class="community-profile-head"><div class="community-profile-photo">${image ? `<img src="${escapeHtml(image)}" alt="${escapeHtml(name)}">` : escapeHtml(name.slice(0, 1))}</div><span class="eyebrow">${escapeHtml(profile.role)} profile</span><h2>${escapeHtml(name)} ${profile.verified ? `<small title="Verified">✓</small>` : ""}</h2>${profile.username ? `<p>@${escapeHtml(profile.username)}</p>` : ""}</section><section class="community-profile-body">${profile.bio ? `<p>${escapeHtml(profile.bio)}</p>` : `<p class="muted">This member has not added a public introduction yet.</p>`}<div class="profile-facts">${details.filter(Boolean).map(value => `<span>${escapeHtml(value)}</span>`).join("")}</div>${profile.skills.length ? `<div class="profile-skills">${profile.skills.map(skill => `<span>${escapeHtml(skill)}</span>`).join("")}</div>` : ""}${links.length ? `<div class="profile-links">${links.map(([label, url]) => `<a href="${escapeHtml(url)}" target="_blank" rel="noopener">${label} ↗</a>`).join("")}</div>` : ""}<div class="profile-timeline"><div><span class="eyebrow">Activity</span><h3>Posts</h3><small>${memberPosts.length} post${memberPosts.length === 1 ? "" : "s"}</small></div>${timeline}</div></section>`;
    dialog.querySelector(".modal-close")!.addEventListener("click", () => dialog.close());
    dialog.querySelectorAll<HTMLButtonElement>("[data-profile-post]").forEach(button => button.addEventListener("click", () => { const post = memberPosts.find(item => item.id === button.dataset.profilePost); if (post) void openCommunityPost(post); }));
  } catch (error) { dialog.querySelector<HTMLElement>(".loading-card")!.outerHTML = `<div class="error-card"><strong>Profile couldn’t be loaded.</strong><p>${escapeHtml(error instanceof Error ? error.message : "Please try again.")}</p></div>`; }
}

async function openCommunityPost(post: CommunityPost, onPostChanged?: () => void) {
  const dialog = document.createElement("dialog"); dialog.className = "community-detail-modal";
  dialog.innerHTML = `<div class="detail-heading"><div><span class="eyebrow">Community post</span><h2>${escapeHtml(post.authorName)}</h2><p>${post.username ? `@${escapeHtml(post.username)}` : escapeHtml(post.authorRole)}</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="community-detail-content"><p>${renderPostText(post.content)}</p>${post.imageUrl ? `<img class="post-image" src="${escapeHtml(post.imageUrl)}" alt="Post attachment">` : ""}</div><div class="reaction-picker">${["like", "love", "celebrate", "insightful", "support"].map(reaction => `<button data-detail-reaction="${reaction}" class="${post.reactions[auth.currentUser!.uid] === reaction ? "selected" : ""}">${reaction === "like" ? "👍" : reaction === "love" ? "❤️" : reaction === "celebrate" ? "🎉" : reaction === "insightful" ? "💡" : "👏"} ${reaction}</button>`).join("")}<button data-detail-reaction="" class="remove">Remove</button></div><section class="comment-section"><div class="section-title"><div><span class="eyebrow">Conversation</span><h2>Comments</h2></div></div><form id="comment-form"><input id="comment-content" minlength="1" maxlength="1500" required placeholder="Write a comment…"><button type="submit">Post</button></form><div id="comment-status"></div><div id="comment-list"><div class="loading-card">Loading comments…</div></div></section>`;
  document.body.append(dialog); dialog.querySelector(".modal-close")!.addEventListener("click", () => dialog.close()); dialog.addEventListener("close", () => dialog.remove()); dialog.showModal();
  let comments: CommunityComment[] = []; const replies = new Map<string, CommunityReply[]>();
  const replyMarkup = (commentId: string, reply: CommunityReply) => `<article class="community-reply ${reply.parentReplyId ? "nested" : ""}"><div class="community-avatar">${reply.userImage ? `<img src="${escapeHtml(reply.userImage)}" alt="">` : escapeHtml(reply.userName.slice(0, 1))}</div><div><button class="comment-author" data-comment-profile="${escapeHtml(reply.userId)}" data-comment-name="${escapeHtml(reply.userName)}" data-comment-image="${escapeHtml(reply.userImage)}">${escapeHtml(reply.userName)}</button>${reply.userReplyingTo ? `<small>Replying to ${escapeHtml(reply.userReplyingTo)}</small>` : ""}<p>${renderPostText(reply.content)}</p><div class="comment-actions"><button data-reply-comment="${escapeHtml(commentId)}" data-reply-parent="${escapeHtml(reply.id)}">Reply</button>${reply.userId === auth.currentUser!.uid ? `<button data-edit-reply="${escapeHtml(commentId)}/${escapeHtml(reply.id)}">Edit</button><button data-delete-reply="${escapeHtml(commentId)}/${escapeHtml(reply.id)}">Delete</button>` : ""}</div></div></article>`;
  const paintComments = () => {
    dialog.querySelector<HTMLElement>("#comment-list")!.innerHTML = comments.length ? comments.map(comment => `<section class="comment-thread"><article class="community-comment"><div class="community-avatar">${comment.userImage ? `<img src="${escapeHtml(comment.userImage)}" alt="">` : escapeHtml(comment.userName.slice(0, 1))}</div><div><button class="comment-author" data-comment-profile="${escapeHtml(comment.userId)}" data-comment-name="${escapeHtml(comment.userName)}" data-comment-image="${escapeHtml(comment.userImage)}">${escapeHtml(comment.userName)}</button><small>${comment.createdAt ? new Date(comment.createdAt).toLocaleString() : "Just now"}</small><p>${renderPostText(comment.content)}</p><div class="comment-actions"><button data-reply-comment="${escapeHtml(comment.id)}">Reply</button>${comment.userId === auth.currentUser!.uid ? `<button data-edit-comment="${escapeHtml(comment.id)}">Edit</button><button data-delete-comment="${escapeHtml(comment.id)}">Delete</button>` : ""}</div></div></article><div class="reply-list">${(replies.get(comment.id) || []).map(reply => replyMarkup(comment.id, reply)).join("")}</div></section>`).join("") : `<div class="empty-card"><strong>No comments yet</strong><p>Start a helpful conversation.</p></div>`;
    const status = dialog.querySelector<HTMLElement>("#comment-status")!;
    dialog.querySelectorAll<HTMLButtonElement>("[data-comment-profile]").forEach(button => button.addEventListener("click", () => void openCommunityMemberProfile(button.dataset.commentProfile!, "member", button.dataset.commentName || "IT Connect member", button.dataset.commentImage || "")));
    dialog.querySelectorAll<HTMLButtonElement>("[data-delete-comment]").forEach(button => button.addEventListener("click", async () => { const comment = comments.find(item => item.id === button.dataset.deleteComment); if (!comment || !confirm("Delete this comment?")) return; button.disabled = true; try { await deletePostComment(auth.currentUser!.uid, post.id, comment); comments = comments.filter(item => item !== comment); replies.delete(comment.id); post.commentCount = comments.length; const latest = comments.at(-1); post.latestComment = latest ? { userName: latest.userName, content: latest.content, createdAt: latest.createdAt } : null; paintComments(); onPostChanged?.(); } catch (error) { button.disabled = false; status.textContent = error instanceof Error ? error.message : "Comment could not be deleted."; } }));
    dialog.querySelectorAll<HTMLButtonElement>("[data-edit-comment]").forEach(button => button.addEventListener("click", async () => { const comment = comments.find(item => item.id === button.dataset.editComment); if (!comment) return; const content = prompt("Edit your comment", comment.content); if (!content?.trim() || content.trim() === comment.content) return; try { await updatePostComment(auth.currentUser!.uid, post.id, comment, content); comment.content = content.trim(); paintComments(); } catch (error) { status.textContent = error instanceof Error ? error.message : "Comment could not be updated."; } }));
    dialog.querySelectorAll<HTMLButtonElement>("[data-reply-comment]").forEach(button => button.addEventListener("click", async () => { const commentId = button.dataset.replyComment!; const parent = (replies.get(commentId) || []).find(item => item.id === button.dataset.replyParent); const content = prompt(parent ? `Reply to ${parent.userName}` : "Write a reply"); if (!content?.trim()) return; try { await addCommentReply(auth.currentUser!.uid, currentProfile!, post.id, commentId, content, parent); replies.set(commentId, await listCommentReplies(post.id, commentId)); paintComments(); } catch (error) { status.textContent = error instanceof Error ? error.message : "Reply could not be posted."; } }));
    dialog.querySelectorAll<HTMLButtonElement>("[data-edit-reply]").forEach(button => button.addEventListener("click", async () => { const [commentId, replyId] = button.dataset.editReply!.split("/"); const reply = (replies.get(commentId) || []).find(item => item.id === replyId); if (!reply) return; const content = prompt("Edit your reply", reply.content); if (!content?.trim() || content.trim() === reply.content) return; try { await updateCommentReply(auth.currentUser!.uid, post.id, commentId, reply, content); reply.content = content.trim(); paintComments(); } catch (error) { status.textContent = error instanceof Error ? error.message : "Reply could not be updated."; } }));
    dialog.querySelectorAll<HTMLButtonElement>("[data-delete-reply]").forEach(button => button.addEventListener("click", async () => { const [commentId, replyId] = button.dataset.deleteReply!.split("/"); const reply = (replies.get(commentId) || []).find(item => item.id === replyId); if (!reply || !confirm("Delete this reply?")) return; button.disabled = true; try { await deleteCommentReply(auth.currentUser!.uid, post.id, commentId, reply); replies.set(commentId, (replies.get(commentId) || []).filter(item => item !== reply)); paintComments(); } catch (error) { button.disabled = false; status.textContent = error instanceof Error ? error.message : "Reply could not be deleted."; } }));
  };
  try { comments = await listPostComments(post.id); await Promise.all(comments.map(async comment => replies.set(comment.id, await listCommentReplies(post.id, comment.id)))); paintComments(); } catch (error) { dialog.querySelector<HTMLElement>("#comment-list")!.innerHTML = `<div class="error-card"><strong>Comments couldn’t be loaded.</strong><p>${escapeHtml(error instanceof Error ? error.message : "Please try again.")}</p></div>`; }
  dialog.querySelectorAll<HTMLButtonElement>("[data-detail-reaction]").forEach(button => button.addEventListener("click", async () => { const reaction = button.dataset.detailReaction || null; button.disabled = true; try { await setPostReaction(auth.currentUser!.uid, post.id, reaction); if (reaction) { post.reactions[auth.currentUser!.uid] = reaction; if (!post.likes.includes(auth.currentUser!.uid)) post.likes.push(auth.currentUser!.uid); } else { delete post.reactions[auth.currentUser!.uid]; post.likes = post.likes.filter(id => id !== auth.currentUser!.uid); } dialog.querySelectorAll("[data-detail-reaction]").forEach(item => item.classList.toggle("selected", Boolean(reaction) && (item as HTMLElement).dataset.detailReaction === reaction)); } finally { button.disabled = false; } }));
  dialog.querySelector<HTMLFormElement>("#comment-form")!.addEventListener("submit", async event => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; const input = form.querySelector<HTMLInputElement>("#comment-content")!; const button = form.querySelector<HTMLButtonElement>("button")!; button.disabled = true; try { await addPostComment(auth.currentUser!.uid, currentProfile!, post.id, input.value); input.value = ""; comments = await listPostComments(post.id); post.commentCount = comments.length; const latest = comments.at(-1); post.latestComment = latest ? { userName: latest.userName, content: latest.content, createdAt: latest.createdAt } : null; paintComments(); onPostChanged?.(); } catch (error) { dialog.querySelector<HTMLElement>("#comment-status")!.textContent = error instanceof Error ? error.message : "Comment could not be posted."; } finally { button.disabled = false; } });
}

async function renderSavedAndRecent() {
  const content = document.querySelector<HTMLElement>(".content")!;
  content.innerHTML = `<section class="browse-head"><div><span class="eyebrow">Opportunity library</span><h1>Saved and recent</h1><p>Return to placements you bookmarked or recently explored.</p></div><a class="back-link" href="#dashboard">← Dashboard</a></section><div class="library-tabs"><button class="active" data-library="saved">Saved</button><button data-library="recent">Recently viewed</button></div><div id="opportunity-library"><div class="loading-card">Loading your opportunities…</div></div>`;
  try {
    if (!internshipCache.length) internshipCache = await listInternships();
    const saved = await listSavedInternships(auth.currentUser!.uid, internshipCache);
    savedIds = new Set(saved.map(item => item.id));
    const merged = new Map(internshipCache.map(item => [item.id, item])); saved.forEach(item => merged.set(item.id, item)); internshipCache = [...merged.values()];
    const recentIds = getRecentInternshipIds(auth.currentUser!.uid);
    const recent = recentIds.flatMap(id => { const item = merged.get(id); return item ? [item] : []; });
    const card = (item: Internship, scope: "saved" | "recent") => `<article class="library-card ${item.removed ? "removed" : ""}"><div class="library-company"><div class="company-logo">${item.companyLogo ? `<img src="${escapeHtml(item.companyLogo)}" alt="">` : escapeHtml(item.companyName.slice(0, 1))}</div><div><strong>${escapeHtml(item.companyName)}</strong><small>${escapeHtml([item.state, item.lga].filter(Boolean).join(", ") || "Location not specified")}</small></div></div><span class="library-state">${item.removed ? "Opportunity removed" : item.status || "Open"}</span><h2>${escapeHtml(item.title)}</h2><p>${escapeHtml(item.description || "Open this placement to review its details.")}</p><div class="chips"><span>${escapeHtml(item.industry || item.course || "General")}</span><span>${escapeHtml(item.duration)}</span><span class="${item.paid ? "paid" : ""}">${item.paid ? `₦${(item.stipend || 0).toLocaleString()}` : "Unpaid"}</span></div><div class="library-actions"><button data-library-view="${escapeHtml(item.id)}">View details</button><button class="secondary-action" data-library-save="${escapeHtml(item.id)}">${scope === "saved" ? "Remove saved" : savedIds.has(item.id) ? "Saved" : "Save"}</button></div></article>`;
    const paint = (scope: "saved" | "recent") => {
      const items = scope === "saved" ? saved.filter(item => savedIds.has(item.id)) : recent;
      document.querySelector<HTMLElement>("#opportunity-library")!.innerHTML = items.length ? `<div class="library-grid">${items.map(item => card(item, scope)).join("")}</div>` : `<div class="empty-card"><strong>${scope === "saved" ? "No saved opportunities" : "No recently viewed opportunities"}</strong><p>${scope === "saved" ? "Use the heart button while browsing to keep opportunities here." : "Opportunities appear here after you open their details."}</p><a class="primary inline" href="#internships">Browse opportunities</a></div>`;
      document.querySelectorAll<HTMLButtonElement>("[data-library-view]").forEach(button => button.addEventListener("click", () => showInternship(button.dataset.libraryView!)));
      document.querySelectorAll<HTMLButtonElement>("[data-library-save]").forEach(button => button.addEventListener("click", async () => { const item = merged.get(button.dataset.librarySave!); if (!item) return; button.disabled = true; const wasSaved = savedIds.has(item.id); try { await toggleSaved(auth.currentUser!.uid, item, wasSaved); wasSaved ? savedIds.delete(item.id) : savedIds.add(item.id); paint(scope); } catch (error) { button.disabled = false; button.textContent = error instanceof Error ? error.message : "Try again"; } }));
    };
    paint("saved");
    document.querySelectorAll<HTMLButtonElement>("[data-library]").forEach(button => button.addEventListener("click", () => { document.querySelectorAll("[data-library]").forEach(tab => tab.classList.remove("active")); button.classList.add("active"); paint(button.dataset.library as "saved" | "recent"); }));
  } catch (error) {
    document.querySelector<HTMLElement>("#opportunity-library")!.innerHTML = `<div class="error-card"><strong>We couldn’t load your opportunity library.</strong><p>${escapeHtml(error instanceof Error ? error.message : "Please try again.")}</p></div>`;
  }
}

async function renderTraining() {
  const content = document.querySelector<HTMLElement>(".content")!;
  content.innerHTML = `<section class="browse-head"><div><span class="eyebrow">Industrial training</span><h1>Training progress</h1><p>Keep track of your active placement, milestones and completion.</p></div><a class="back-link" href="#dashboard">← Dashboard</a></section><div class="loading-card">Loading your training record…</div>`;
  try {
    const applications = await listStudentApplications(auth.currentUser!.uid);
    const accepted = applications.filter(item => ["accepted", "approved", "hired", "completed"].includes(item.status) || ["active", "completed"].includes(item.trainingStatus.toLowerCase()));
    if (!accepted.length) {
      content.innerHTML += `<div class="empty-card"><strong>No active training yet</strong><p>Your training workspace will open when an application is accepted.</p><a class="primary inline" href="#applications">Check applications</a></div>`;
      content.querySelector(".loading-card")?.remove();
      return;
    }
    const item = accepted[0];
    const start = item.startDate ? new Date(item.startDate) : null; const end = item.endDate ? new Date(item.endDate) : null; const now = Date.now();
    const calculatedProgress = start && end && end.getTime() > start.getTime() ? Math.round(Math.max(0, Math.min(1, (now - start.getTime()) / (end.getTime() - start.getTime()))) * 100) : 0;
    const progress = item.trainingStatus.toLowerCase() === "completed" || item.status === "completed" ? 100 : item.trainingProgress || calculatedProgress;
    const formatDate = (value: string) => value && !Number.isNaN(new Date(value).getTime()) ? new Date(value).toLocaleDateString(undefined, { day: "numeric", month: "long", year: "numeric" }) : "Not specified";
    const daysRemaining = end ? Math.max(0, Math.ceil((end.getTime() - now) / 86400000)) : 0;
    const updates = item.trainingUpdates.length ? item.trainingUpdates : [{ title: "Placement accepted", date: item.submittedAt, note: `Your placement with ${item.companyName} is ready.` }];
    content.querySelector(".loading-card")?.remove();
    content.insertAdjacentHTML("beforeend", `<section class="training-hero"><div><span class="eyebrow">${escapeHtml(item.trainingStatus || "Active placement")}</span><h2>${escapeHtml(item.title)}</h2><p>${escapeHtml(item.companyName)} · ${escapeHtml(item.location)}</p></div><div class="training-ring" style="--training-progress:${progress * 3.6}deg"><strong>${progress}%</strong><span>complete</span></div></section><section class="training-stats"><article><small>Start date</small><strong>${formatDate(item.startDate)}</strong></article><article><small>Expected completion</small><strong>${formatDate(item.endDate)}</strong></article><article><small>Time remaining</small><strong>${end ? `${daysRemaining} days` : item.selectedDuration}</strong></article><article><small>Placement status</small><strong>${escapeHtml(item.trainingStatus || item.status)}</strong></article></section><div class="training-layout"><section class="training-panel"><span class="eyebrow">Journey</span><h2>Progress and updates</h2><div class="training-bar"><i style="width:${progress}%"></i></div><div class="training-updates">${updates.map((update, index) => `<article><i>${index + 1}</i><div><strong>${escapeHtml(update.title)}</strong><small>${update.date ? new Date(update.date).toLocaleDateString() : "Latest update"}</small><p>${escapeHtml(update.note || "Your training record was updated.")}</p></div></article>`).join("")}</div></section><aside class="training-panel training-actions"><span class="eyebrow">Completion</span><h2>Your records</h2><p>Completion documents become available after the company and relevant authority finish their reviews.</p>${item.authorityStatus ? `<div><small>Authority status</small><strong>${escapeHtml(item.authorityStatus)}</strong></div>` : ""}${item.authorityLetterUrl ? `<a href="${escapeHtml(item.authorityLetterUrl)}" target="_blank" rel="noopener">Download authority letter →</a>` : ""}${item.certificateUrl ? `<a class="certificate-link" href="${escapeHtml(item.certificateUrl)}" target="_blank" rel="noopener"><span>✓</span><div><strong>Completion certificate</strong><small>View or download certificate</small></div></a>` : `<div class="certificate-pending"><span>○</span><div><strong>Certificate pending</strong><small>Available after training completion</small></div></div>`}<button class="secondary-action" id="training-application">View original application</button></aside></div>`);
    content.querySelector<HTMLButtonElement>("#training-application")!.addEventListener("click", () => openApplicationDetails(item));
  } catch (error) {
    content.querySelector(".loading-card")!.outerHTML = `<div class="error-card"><strong>We couldn’t load your training record.</strong><p>${escapeHtml(error instanceof Error ? error.message : "Please try again.")}</p></div>`;
  }
}

function openApplicationDetails(item: Awaited<ReturnType<typeof listStudentApplications>>[number]) {
  const dialog = document.createElement("dialog");
  dialog.className = "application-detail-modal";
  const date = (value: string | number) => value && !Number.isNaN(new Date(value).getTime()) ? new Date(value).toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" }) : "Not specified";
  const statusLabel = item.status === "rejected" ? "Not selected" : item.status.replace(/_/g, " ");
  const generatedHistory = [{ status: "Application submitted", date: item.submittedAt, note: "Your application was delivered to the company." }, ...item.statusHistory];
  if (item.status !== "pending" && !generatedHistory.some(event => event.status.toLowerCase() === item.status)) generatedHistory.push({ status: statusLabel, date: 0, note: "Current application status." });
  dialog.innerHTML = `<div class="detail-heading"><div><span class="eyebrow">${escapeHtml(item.companyName)}</span><h2>${escapeHtml(item.title)}</h2><p>${escapeHtml(item.location)}</p></div><button class="modal-close" aria-label="Close">×</button></div>${item.removed ? `<div class="detail-notice danger"><strong>Opportunity removed</strong><span>This historic application remains available for your records.</span></div>` : item.cancelled ? `<div class="detail-notice"><strong>Application withdrawn</strong><span>This submission is no longer active.</span></div>` : ""}<div class="detail-status"><div><small>Current status</small><strong class="status-pill ${escapeHtml(item.status)}">${escapeHtml(statusLabel)}</strong></div><div><small>Submitted</small><strong>${date(item.submittedAt)}</strong></div><div><small>Training period</small><strong>${date(item.startDate)} – ${date(item.endDate)}</strong></div><div><small>Duration</small><strong>${escapeHtml(item.selectedDuration)}</strong></div></div><div class="detail-columns"><section><span class="eyebrow">Application</span><h3>Training statement</h3><p>${escapeHtml(item.description || "No training statement was included.")}</p><span class="eyebrow detail-label">Documents</span><div class="detail-documents">${item.documents.length ? item.documents.map(file => `<a href="${escapeHtml(file.url)}" target="_blank" rel="noopener"><span>↗</span><div><strong>${escapeHtml(file.name || file.kind || "Document")}</strong><small>Open document</small></div></a>`).join("") : `<p>No documents are attached to this record.</p>`}</div></section><section><span class="eyebrow">Progress</span><h3>Status timeline</h3><div class="detail-timeline">${generatedHistory.map((event, index) => `<div class="${index === generatedHistory.length - 1 ? "current" : "done"}"><i></i><span></span><article><strong>${escapeHtml(event.status)}</strong><small>${event.date ? date(event.date) : "Latest update"}</small>${event.note ? `<p>${escapeHtml(event.note)}</p>` : ""}</article></div>`).join("")}</div>${item.authorityStatus || item.authorityLetterUrl ? `<div class="detail-meta"><small>Authority approval</small><strong>${escapeHtml(item.authorityStatus || "Approved")}</strong>${item.authorityLetterUrl ? `<a href="${escapeHtml(item.authorityLetterUrl)}" target="_blank" rel="noopener">Download authority letter →</a>` : ""}</div>` : ""}${item.paymentStatus || item.refundStatus ? `<div class="detail-meta"><small>Payment and refund</small><strong>${escapeHtml(item.paymentStatus || "No payment status")}</strong>${item.refundStatus ? `<span>Refund: ${escapeHtml(item.refundStatus)}</span>` : ""}</div>` : ""}</section></div>`;
  document.body.append(dialog);
  dialog.querySelector(".modal-close")!.addEventListener("click", () => dialog.close());
  dialog.addEventListener("click", event => { if (event.target === dialog) dialog.close(); });
  dialog.addEventListener("close", () => dialog.remove());
  dialog.showModal();
}

const field = (label: string, name: string, value: unknown, type = "text", placeholder = "", readonly = false) => `<label>${label}<input name="${name}" type="${type}" value="${escapeHtml(String(value || ""))}" placeholder="${escapeHtml(placeholder)}" ${readonly ? "readonly" : ""}></label>`;

async function renderProfile() {
  const content = document.querySelector<HTMLElement>(".content")!;
  content.innerHTML = `<div class="loading-card">Loading your profile…</div>`;
  try {
    const profile = await getStudentProfile(auth.currentUser!.uid); const completion = calculateCompletion(profile);
    content.innerHTML = `<section class="browse-head"><div><span class="eyebrow">Identity and documents</span><h1>Your profile</h1><p>Keep this accurate so companies can evaluate your applications.</p></div><a class="back-link" href="#dashboard">← Dashboard</a></section><div class="profile-layout"><aside class="profile-card"><div class="profile-photo">${profile.imageUrl ? `<img src="${escapeHtml(profile.imageUrl)}" alt="Profile photo">` : escapeHtml(String(profile.fullName || "S").slice(0,1))}</div><h2>${escapeHtml(String(profile.fullName || "Student"))}</h2><p>${escapeHtml(String(profile.courseOfStudy || "Course not added"))}</p><div class="completion-ring" style="--completion:${completion * 3.6}deg"><strong>${completion}%</strong></div><span>Profile complete</span><label class="photo-upload">Change photo<input id="profile-photo" type="file" accept=".jpg,.jpeg,.png,.webp"></label><div id="asset-status" role="status"></div></aside><form id="profile-form" class="profile-form"><section><div class="form-section-title"><span>01</span><div><h2>Personal information</h2><p>Your name and contact details.</p></div></div><div class="profile-fields">${field("Full name","fullName",profile.fullName)}${field("Email","email",profile.email,"email")}${field("Phone number","phoneNumber",profile.phoneNumber,"tel")}</div><label>Professional summary<textarea name="bio" maxlength="500" placeholder="Introduce your interests, strengths, and career goals.">${escapeHtml(String(profile.bio || ""))}</textarea></label></section><section><div class="form-section-title"><span>02</span><div><h2>Education</h2><p>Your current academic information.</p></div></div><div class="profile-fields">${field("Institution","institution",profile.institution)}${field("Course of study","courseOfStudy",profile.courseOfStudy)}${field("Department","department",profile.department)}${field("Level","level",profile.level)}${field("Registration / matric number","registrationNumber",profile.registrationNumber)}</div></section><section><div class="form-section-title"><span>03</span><div><h2>Location and links</h2><p>Used for local opportunity matching.</p></div></div><div class="profile-fields">${field("Current address","currentAddress",profile.currentAddress)}${field("State","stateOfOrigin",profile.stateOfOrigin || profile.state)}${field("Local government area","localGovernmentArea",profile.localGovernmentArea)}${field("LinkedIn URL","linkedinUrl",profile.linkedinUrl,"url")}${field("GitHub URL","githubUrl",profile.githubUrl,"url")}${field("Portfolio URL","portfolioUrl",profile.portfolioUrl,"url")}</div><label>Skills <input name="skills" value="${escapeHtml(Array.isArray(profile.skills) ? profile.skills.join(", ") : "")}" placeholder="JavaScript, UI design, communication"></label></section><section><div class="form-section-title"><span>04</span><div><h2>Emergency contact</h2><p>Visible only where operationally necessary.</p></div></div><div class="profile-fields">${field("Contact name","emergencyContactName",profile.emergencyContactName)}${field("Phone number","emergencyContactPhone",profile.emergencyContactPhone,"tel")}${field("Relationship","emergencyContactRelationship",profile.emergencyContactRelationship)}${field("Email","emergencyContactEmail",profile.emergencyContactEmail,"email")}</div></section><section><div class="form-section-title"><span>05</span><div><h2>Reusable documents</h2><p>Upload once and keep your application documents ready.</p></div></div><div class="document-grid">${documentTile("Resume","resume",Boolean(profile.resumeUrl),profile.resumeUrl as string)}${documentTile("Student ID card","idCard",Boolean(profile.idCards?.length),profile.idCards?.[profile.idCards.length-1])}${documentTile("IT letter","itLetter",Boolean(profile.itLetters?.length),profile.itLetters?.[profile.itLetters.length-1])}</div></section><div id="profile-status" role="status"></div><div class="sticky-save"><span>Changes are saved securely to your student profile.</span><button class="primary" type="submit">Save profile</button></div></form></div>`;
    const registrationInput = content.querySelector<HTMLInputElement>('input[name="registrationNumber"]'); if (registrationInput) { const registrationLabel = registrationInput.closest("label"); if (registrationLabel) { registrationLabel.firstChild!.textContent = "Student registration number"; registrationLabel.insertAdjacentHTML("afterend", field("Matric number", "matricNumber", profile.matricNumber)); } }
    bindProfile(profile);
  } catch (error) { content.innerHTML = `<div class="error-card"><strong>We couldn’t open your profile.</strong><p>${escapeHtml(error instanceof Error ? error.message : "Please try again.")}</p></div>`; }
}

function documentTile(label: string, kind: string, uploaded: boolean, url?: string) { return `<div class="document-tile ${uploaded ? "uploaded" : ""}"><span>${uploaded ? "✓" : "+"}</span><div><strong>${label}</strong><small>${uploaded ? "Ready to use" : "PDF, JPG, or PNG"}</small></div>${url ? `<a href="${escapeHtml(url)}" target="_blank" rel="noopener">View</a>` : ""}<label>${uploaded ? "Replace" : "Upload"}<input data-profile-document="${kind}" type="file" accept=".pdf,.jpg,.jpeg,.png"></label></div>`; }

function bindProfile(profile: Record<string, unknown>) {
  const uid = auth.currentUser!.uid; const status = document.querySelector<HTMLElement>("#profile-status")!; const assetStatus = document.querySelector<HTMLElement>("#asset-status")!;
  document.querySelector<HTMLInputElement>("#profile-photo")!.addEventListener("change", async event => { const file = (event.currentTarget as HTMLInputElement).files?.[0]; if (!file) return; assetStatus.textContent = "Uploading photo…"; try { await uploadProfileAsset(uid,"photo",file); assetStatus.textContent = "Photo updated."; await renderProfile(); } catch (error) { assetStatus.textContent = error instanceof Error ? error.message : "Upload failed."; } });
  document.querySelectorAll<HTMLInputElement>("[data-profile-document]").forEach(input => input.addEventListener("change", async () => { const file = input.files?.[0]; if (!file) return; status.textContent = `Uploading ${file.name}…`; input.disabled = true; try { await uploadProfileAsset(uid,input.dataset.profileDocument as "resume"|"idCard"|"itLetter",file); status.textContent = "Document uploaded."; await renderProfile(); } catch (error) { status.textContent = error instanceof Error ? error.message : "Upload failed."; input.disabled = false; } }));
  document.querySelector<HTMLFormElement>("#profile-form")!.addEventListener("submit", async event => { event.preventDefault(); const formElement = event.currentTarget as HTMLFormElement; const form = new FormData(formElement); const values: Record<string,string|string[]> = {}; for (const [key,value] of form.entries()) if (typeof value === "string") values[key] = key === "skills" ? value.split(",") : value; const button = formElement.querySelector<HTMLButtonElement>('button[type="submit"]')!; button.disabled = true; button.textContent = "Saving…"; try { await updateStudentProfile(uid,values); currentProfile = { ...currentProfile!, name: String(values.fullName || currentProfile!.name), state: String(values.stateOfOrigin || currentProfile!.state || "") }; status.textContent = "Profile saved successfully."; button.textContent = "Saved"; setTimeout(() => { button.disabled = false; button.textContent = "Save profile"; },1200); } catch (error) { status.textContent = error instanceof Error ? error.message : "Save failed."; button.disabled = false; button.textContent = "Save profile"; } });
  void profile;
}

function bindTheme() {
  document.querySelector<HTMLButtonElement>("#theme-toggle")?.addEventListener("click", () => applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark"));
}

async function start() {
  await configureDefaultPersistence();
  onAuthStateChanged(auth, async (user) => {
    if (registrationInProgress || claimInProgress) return;
    if (!user || user.isAnonymous) {
      void presenceCleanup?.();
      presenceCleanup = null;
      return claimRequested() ? renderClaimAccount() : signupRequested() ? renderSignup() : renderLogin();
    }
    if (claimRequested()) return renderClaimAccount();
    root.innerHTML = `<div class="boot">Preparing your workspace…</div>`;
    try { const profile = await resolveProfile(user); assertWorkspaceAccess(profile); await presenceCleanup?.(); presenceCleanup = startPresence(user.uid); renderWorkspace(profile); }
    catch (error) { await signOut(auth); renderLogin(error instanceof Error ? error.message : "Unable to open this account."); }
  });
}
window.addEventListener("hashchange", () => { if (claimRequested()) return renderClaimAccount(); if (!auth.currentUser || auth.currentUser.isAnonymous) signupRequested() ? renderSignup() : renderLogin(); else void routeWorkspace(); });
void start();
